window.SOZPAED={"id":"BRC-LG03-LS05","title":"Marketingziele und -strategien entwickeln","version":"2026-10-15.lg03.2","priorityStatement":"Ich entwickle auf Grundlage von Unternehmenslage, Leitbild und Marktforschungsbefunden ein widerspruchsarmes System von Marketingzielen und begründe eine kombinierte Wettbewerbs-, Marktbearbeitungs- und Wachstumsstrategie.","competencies":[{"label":"Fachkompetenz","weight":5,"statement":"Ich erläutere Zielbeziehungen und kombiniere Porter, Segmentierung sowie Ansoff als unterschiedliche Entscheidungsperspektiven sachgerecht.","id":"BRC-LG03-LS05-F"},{"label":"Personalkompetenz","weight":4,"statement":"Ich prüfe Wunschziele an verfügbaren Ressourcen und benenne Zielkonflikte offen.","id":"BRC-LG03-LS05-P"},{"label":"Sozialkompetenz","weight":4,"statement":"Ich führe Interessen von Finanzen, Produktentwicklung, Logistik und Marketing zu einer begründeten Entscheidung zusammen.","id":"BRC-LG03-LS05-S"},{"label":"Methodenkompetenz","weight":4,"statement":"Ich vergleiche mindestens zwei konsistente Strategiebündel anhand gemeinsamer Kriterien und operationalisiere Ziele.","id":"BRC-LG03-LS05-M"},{"label":"Medienkompetenz","weight":3,"statement":"Ich erstelle eine kurze Beschlussvorlage mit kenntlich gemachter Datenbasis und überprüfbaren Zielgrößen.","id":"BRC-LG03-LS05-D"}],"pages":{"index.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Marketingziele und -strategien entwickeln</h1></section><section class=\"card relevance\"><h2>Darum ist das Thema relevant</h2><figure class=\"story-photo\" data-media-key=\"orientation\"></figure><p>„Wir wollen wachsen“ hilft dem Produktionsteam kaum bei einer Entscheidung. Ein brauchbares Marketingkonzept sagt, für wen das Angebot gedacht ist, wodurch es überzeugen soll und woran sein Erfolg erkennbar wird. Sie verbinden deshalb Kundenwissen mit messbaren Zielen und prüfen, ob das gewünschte Wachstum zu Personal, Marke und Kühlkette passt.</p>\n</section><section class=\"card priority-section\"><h2>Kompetenzprofil</h2><section class=\"weight-radar\"><svg viewBox=\"0 0 700 435\" role=\"img\" aria-label=\"Kompetenznetz und Gewichtung\"><title>Kompetenznetz</title><polygon points=\"350.00,189.17 374.57,207.02 365.18,235.90 334.82,235.90 325.43,207.02\" fill=\"none\" stroke=\"#c8dce7\"></polygon><polygon points=\"350.00,163.33 399.14,199.03 380.37,256.80 319.63,256.80 300.86,199.03\" fill=\"none\" stroke=\"#c8dce7\"></polygon><polygon points=\"350.00,137.50 423.71,191.05 395.55,277.70 304.45,277.70 276.29,191.05\" fill=\"none\" stroke=\"#c8dce7\"></polygon><polygon points=\"350.00,111.67 448.28,183.07 410.74,298.60 289.26,298.60 251.72,183.07\" fill=\"none\" stroke=\"#c8dce7\"></polygon><polygon points=\"350.00,85.83 472.84,175.09 425.92,319.50 274.08,319.50 227.16,175.09\" fill=\"none\" stroke=\"#c8dce7\"></polygon><polygon points=\"350.00,60.00 497.41,167.10 441.11,340.40 258.89,340.40 202.59,167.10\" fill=\"none\" stroke=\"#c8dce7\"></polygon><line x1=\"350\" y1=\"215\" x2=\"350.0\" y2=\"60.0\" stroke=\"#d2e3ea\"></line><text x=\"350.0\" y=\"19.958333333333343\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#173a63\" font-size=\"15\">Fachkompetenz</text><line x1=\"350\" y1=\"215\" x2=\"497.4137600257488\" y2=\"167.10236587188317\" stroke=\"#d2e3ea\"></line><text x=\"535.4956480324006\" y=\"154.7288103887863\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#173a63\" font-size=\"15\">Personalkompetenz</text><line x1=\"350\" y1=\"215\" x2=\"441.1067141053333\" y2=\"340.39763412811686\" stroke=\"#d2e3ea\"></line><text x=\"464.64261524921113\" y=\"372.79202294454706\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#173a63\" font-size=\"15\">Sozialkompetenz</text><line x1=\"350\" y1=\"215\" x2=\"258.8932858946667\" y2=\"340.39763412811686\" stroke=\"#d2e3ea\"></line><text x=\"235.35738475078892\" y=\"372.79202294454706\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#173a63\" font-size=\"15\">Methodenkompetenz</text><line x1=\"350\" y1=\"215\" x2=\"202.5862399742512\" y2=\"167.1023658718831\" stroke=\"#d2e3ea\"></line><text x=\"164.50435196759943\" y=\"154.72881038878623\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#173a63\" font-size=\"15\">Medienkompetenz</text><polygon points=\"350.00,85.83 448.28,183.07 410.74,298.60 289.26,298.60 276.29,191.05\" fill=\"#afca0b\" fill-opacity=\".27\" stroke=\"#009bd9\" stroke-width=\"2.5\"></polygon></svg></section><div class=\"competence-cards orientation-competencies\"><article class=\"card\"><h3><strong>Fachkompetenz</strong></h3><p>Ich entwickle auf Grundlage von Unternehmenslage, Leitbild und Marktforschungsbefunden ein widerspruchsarmes System von Marketingzielen und begründe eine kombinierte Wettbewerbs-, Marktbearbeitungs- und Wachstumsstrategie.</p></article><article class=\"card\"><h3><strong>Personalkompetenz</strong></h3><p>Ich prüfe Wunschziele an verfügbaren Ressourcen und benenne Zielkonflikte offen.</p></article><article class=\"card\"><h3><strong>Sozialkompetenz</strong></h3><p>Ich führe Interessen von Finanzen, Produktentwicklung, Logistik und Marketing zu einer begründeten Entscheidung zusammen.</p></article><article class=\"card\"><h3><strong>Methodenkompetenz</strong></h3><p>Ich vergleiche mindestens zwei konsistente Strategiebündel anhand gemeinsamer Kriterien und operationalisiere Ziele.</p></article><article class=\"card\"><h3><strong>Medienkompetenz</strong></h3><p>Ich erstelle eine kurze Beschlussvorlage mit kenntlich gemachter Datenbasis und überprüfbaren Zielgrößen.</p></article></div></section><section class=\"orientation-completion no-print\" data-orientation-completion=\"\" contenteditable=\"false\"><label><input type=\"checkbox\" data-orientation-complete=\"\" disabled=\"\">Orientierung gelesen</label><p class=\"progress-counter\" data-progress-status=\"\" role=\"status\"></p></section>","handlungssituation.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Handlungssituation</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"card situation-prose\"><figure class=\"story-photo\" data-media-key=\"situation\"></figure><p>Im Besprechungsraum der BioCasa AG hängen drei große Karten: „Mehr Kunden“, „Bessere Marge“ und „Weniger Abschriften“. Alle vier Gründer können unterschreiben, dass diese Dinge wichtig sind. Sobald es um das Vorgehen geht, wird die Einigkeit kleiner. Fari möchte die Küchenkompetenz nutzen und eine rein pflanzliche Gartenpizza für ein unkompliziertes Abendessen nach der Arbeit entwickeln. Julia sieht dazu passende Hinweise in den Befragungen, warnt jedoch davor, aus 240 freiwilligen Antworten eine sichere Marktprognose zu machen. Aluna erinnert daran, dass zusätzliche Varianten auch zusätzliche Lagerplätze, kleinere Produktionslose und aufwendigere Kühltransporte bedeuten.</p>\n<p>Christian bringt das Jahresziel mit: Der Umsatz soll von 2,4 auf 2,64 Millionen Euro steigen, der absolute Jahres-Deckungsbeitrag mindestens 900.000 Euro erreichen. Gleichzeitig soll die Verderbquote von 3,5 auf höchstens 2,0 Prozent sinken. „Wenn wir nur mehr produzieren und anschließend mehr wegwerfen, haben wir nichts gewonnen.“ Ein niederländischer Händler interessiert sich bereits für einen Test. Julia möchte diese Chance nutzen, aber keinen unvorbereiteten Rollout versprechen.</p>\n<p>Ein Vertriebsmitarbeiter schlägt vor, mit starken Preisnachlässen möglichst viele neue Gruppen anzusprechen. Fari hält dagegen: „Dann investieren wir in ein gutes Produkt und erklären danach nur noch, warum es billig ist.“ Eine andere Idee lautet, alle Kräfte auf zwei Varianten für berufstätige Käufer in Norddeutschland zu konzentrieren. Das könnte zur Größe des Unternehmens passen, würde aber andere Kundenwünsche zunächst zurückstellen.</p>\n<p>Für den nächsten Vorstandstermin fehlt eine entscheidungsfähige Vorlage. Ihr Team soll keine Sammlung unverbindlicher Wünsche liefern. Erwartet werden messbare Ziele und ein strategischer Zusammenhang: Welche Kunden spricht BioCasa vorrangig an, wodurch entsteht für diese ein Vorteil, und mit welchen Produkten in welchen Märkten soll das Wachstum erfolgen? Begründen Sie dabei ausdrücklich, was im Pilotjahr noch nicht begonnen werden sollte.</p>\n</section><section class=\"card quiz-check\" data-situation-quiz><h2>Kurz prüfen · Handlungssituation</h2><p>Wählen Sie jeweils die begründete Antwort.</p><details><summary>1. Gemeinsame Anliegen<span data-quiz-marker></span></summary><div data-quiz-question=\"situation-1\"><p>Welche drei Anliegen stehen auf den Karten im Besprechungsraum?</p><label><input type=\"radio\" name=\"situation-1\" value=\"A\"><span>„Neue Rechtsform“, „Sofortiger Börsengang“ und „Alle Anteile verkaufen“.</span></label><label><input type=\"radio\" name=\"situation-1\" value=\"B\"><span>„Weniger Informationen“, „Mehr Fehlbestellungen“ und „Keine Tests“.</span></label><label><input type=\"radio\" name=\"situation-1\" value=\"C\"><span>„Nur Pizza-Kits“, „Keine Kühlkette“ und „Keine Produktion“.</span></label><label><input type=\"radio\" name=\"situation-1\" value=\"D\"><span>„Unbegrenzte Varianten“, „Unbegrenztes Budget“ und „Unbegrenzte Kapazität“.</span></label><label><input type=\"radio\" name=\"situation-1\" value=\"E\"><span>„Mehr Kunden“, „Bessere Marge“ und „Weniger Abschriften“.</span></label><label><input type=\"radio\" name=\"situation-1\" value=\"F\"><span>„Weniger Kunden“, „Keine Preise“ und „Keine Liefertermine“.</span></label><div class=\"quiz-actions\"><button data-quiz-submit>Antwort prüfen</button><button data-quiz-reset>Auswahl löschen</button></div><p class=\"quiz-feedback\" data-quiz-feedback hidden role=\"status\"></p></div></details><details><summary>2. Vorgegebene Jahresziele<span data-quiz-marker></span></summary><div data-quiz-question=\"situation-2\"><p>Welche Zielwerte bringt Christian in das Gespräch ein?</p><label><input type=\"radio\" name=\"situation-2\" value=\"A\"><span>2,64 Millionen Euro Umsatz, mindestens 900.000 Euro absoluter Jahres-Deckungsbeitrag und höchstens 2,0 Prozent Verderbquote.</span></label><label><input type=\"radio\" name=\"situation-2\" value=\"B\"><span>2,4 Millionen Euro Umsatz, genau 600.000 Euro Investition und 15 Prozent Verderbquote.</span></label><label><input type=\"radio\" name=\"situation-2\" value=\"C\"><span>900.000 Euro Umsatz, 2,64 Millionen Euro Werbebudget und 48 Prozent Verderbquote.</span></label><label><input type=\"radio\" name=\"situation-2\" value=\"D\"><span>12.000 Euro Umsatz, mindestens 150.000 Euro Abschriften und keine Verderbgrenze.</span></label><label><input type=\"radio\" name=\"situation-2\" value=\"E\"><span>600.000 Euro Umsatz, mindestens 2,4 Millionen Euro Personalaufwand und 10 Prozent Verderbquote.</span></label><label><input type=\"radio\" name=\"situation-2\" value=\"F\"><span>Ein beliebiger Umsatz, unbegrenzte Werbeausgaben und ein vollständiger Verzicht auf Qualitätsziele.</span></label><div class=\"quiz-actions\"><button data-quiz-submit>Antwort prüfen</button><button data-quiz-reset>Auswahl löschen</button></div><p class=\"quiz-feedback\" data-quiz-feedback hidden role=\"status\"></p></div></details><details><summary>3. Alunas Einwand<span data-quiz-marker></span></summary><div data-quiz-question=\"situation-3\"><p>Welche Folgen zusätzlicher Varianten hebt Aluna hervor?</p><label><input type=\"radio\" name=\"situation-3\" value=\"A\"><span>Dass dadurch jede bisherige Kostenposition automatisch entfällt.</span></label><label><input type=\"radio\" name=\"situation-3\" value=\"B\"><span>Dass neue Varianten grundsätzlich ohne Verpackung verkauft werden.</span></label><label><input type=\"radio\" name=\"situation-3\" value=\"C\"><span>Zusätzliche Lagerplätze, kleinere Produktionslose und aufwendigere Kühltransporte.</span></label><label><input type=\"radio\" name=\"situation-3\" value=\"D\"><span>Dass der niederländische Markt automatisch alle zusätzlichen Mengen abnimmt.</span></label><label><input type=\"radio\" name=\"situation-3\" value=\"E\"><span>Dass eine Variante immer die gesamte bisherige Produktion ersetzt.</span></label><label><input type=\"radio\" name=\"situation-3\" value=\"F\"><span>Dass mehr Varianten zwingend weniger Abstimmung und keine Planung benötigen.</span></label><div class=\"quiz-actions\"><button data-quiz-submit>Antwort prüfen</button><button data-quiz-reset>Auswahl löschen</button></div><p class=\"quiz-feedback\" data-quiz-feedback hidden role=\"status\"></p></div></details><details><summary>4. Niederländischer Markt<span data-quiz-marker></span></summary><div data-quiz-question=\"situation-4\"><p>Was ist zum niederländischen Händler bereits bekannt?</p><label><input type=\"radio\" name=\"situation-4\" value=\"A\"><span>Er hat die flächendeckende Vermarktung bereits verbindlich abgeschlossen.</span></label><label><input type=\"radio\" name=\"situation-4\" value=\"B\"><span>Er verlangt den sofortigen Rückzug aus dem norddeutschen Markt.</span></label><label><input type=\"radio\" name=\"situation-4\" value=\"C\"><span>Er übernimmt automatisch sämtliche Kosten neuer Produktvarianten.</span></label><label><input type=\"radio\" name=\"situation-4\" value=\"D\"><span>Er hat sämtliche Forschungsfragen bereits repräsentativ beantwortet.</span></label><label><input type=\"radio\" name=\"situation-4\" value=\"E\"><span>Er hat den gesamten Vorstand von BioCasa ersetzt.</span></label><label><input type=\"radio\" name=\"situation-4\" value=\"F\"><span>Er interessiert sich für einen Test; Julia möchte die Chance nutzen, aber keinen unvorbereiteten Rollout versprechen.</span></label><div class=\"quiz-actions\"><button data-quiz-submit>Antwort prüfen</button><button data-quiz-reset>Auswahl löschen</button></div><p class=\"quiz-feedback\" data-quiz-feedback hidden role=\"status\"></p></div></details><details><summary>5. Strategieauftrag<span data-quiz-marker></span></summary><div data-quiz-question=\"situation-5\"><p>Welche Vorlage erwartet der Vorstand von Ihrem Team?</p><label><input type=\"radio\" name=\"situation-5\" value=\"A\"><span>Eine Sammlung unverbindlicher Wünsche ohne Messgrößen.</span></label><label><input type=\"radio\" name=\"situation-5\" value=\"B\"><span>Ausschließlich einen bereits druckfertigen Werbeprospekt.</span></label><label><input type=\"radio\" name=\"situation-5\" value=\"C\"><span>Nur einen neuen Pizzanamen ohne Bezug zur Unternehmenslage.</span></label><label><input type=\"radio\" name=\"situation-5\" value=\"D\"><span>Messbare Ziele und eine begründete Verbindung von Zielkunden, Wettbewerbsvorteil sowie Produkten und Märkten.</span></label><label><input type=\"radio\" name=\"situation-5\" value=\"E\"><span>Eine endgültige Rezeptur, ohne die strategische Richtung zu klären.</span></label><label><input type=\"radio\" name=\"situation-5\" value=\"F\"><span>Eine ungeprüfte Zusage, alle Kundengruppen gleichzeitig zu bedienen.</span></label><div class=\"quiz-actions\"><button data-quiz-submit>Antwort prüfen</button><button data-quiz-reset>Auswahl löschen</button></div><p class=\"quiz-feedback\" data-quiz-feedback hidden role=\"status\"></p></div></details><p data-quiz-progress role=\"status\"></p><script type=\"application/json\">[{\"id\": \"situation-1\", \"title\": \"Gemeinsame Anliegen\", \"question\": \"Welche drei Anliegen stehen auf den Karten im Besprechungsraum?\", \"options\": [{\"value\": \"A\", \"label\": \"„Neue Rechtsform“, „Sofortiger Börsengang“ und „Alle Anteile verkaufen“.\", \"feedback\": \"Die drei Karten benennen gemeinsame Anliegen. Die Uneinigkeit beginnt bei der Frage, wie BioCasa diese Anliegen in ein abgestimmtes Vorgehen übersetzt.\"}, {\"value\": \"B\", \"label\": \"„Weniger Informationen“, „Mehr Fehlbestellungen“ und „Keine Tests“.\", \"feedback\": \"Die drei Karten benennen gemeinsame Anliegen. Die Uneinigkeit beginnt bei der Frage, wie BioCasa diese Anliegen in ein abgestimmtes Vorgehen übersetzt.\"}, {\"value\": \"C\", \"label\": \"„Nur Pizza-Kits“, „Keine Kühlkette“ und „Keine Produktion“.\", \"feedback\": \"Die drei Karten benennen gemeinsame Anliegen. Die Uneinigkeit beginnt bei der Frage, wie BioCasa diese Anliegen in ein abgestimmtes Vorgehen übersetzt.\"}, {\"value\": \"D\", \"label\": \"„Unbegrenzte Varianten“, „Unbegrenztes Budget“ und „Unbegrenzte Kapazität“.\", \"feedback\": \"Die drei Karten benennen gemeinsame Anliegen. Die Uneinigkeit beginnt bei der Frage, wie BioCasa diese Anliegen in ein abgestimmtes Vorgehen übersetzt.\"}, {\"value\": \"E\", \"label\": \"„Mehr Kunden“, „Bessere Marge“ und „Weniger Abschriften“.\", \"feedback\": \"Die drei Karten benennen gemeinsame Anliegen. Die Uneinigkeit beginnt bei der Frage, wie BioCasa diese Anliegen in ein abgestimmtes Vorgehen übersetzt.\"}, {\"value\": \"F\", \"label\": \"„Weniger Kunden“, „Keine Preise“ und „Keine Liefertermine“.\", \"feedback\": \"Die drei Karten benennen gemeinsame Anliegen. Die Uneinigkeit beginnt bei der Frage, wie BioCasa diese Anliegen in ein abgestimmtes Vorgehen übersetzt.\"}], \"correct\": \"E\"}, {\"id\": \"situation-2\", \"title\": \"Vorgegebene Jahresziele\", \"question\": \"Welche Zielwerte bringt Christian in das Gespräch ein?\", \"options\": [{\"value\": \"A\", \"label\": \"2,64 Millionen Euro Umsatz, mindestens 900.000 Euro absoluter Jahres-Deckungsbeitrag und höchstens 2,0 Prozent Verderbquote.\", \"feedback\": \"Christian nennt diese drei Jahresziele ausdrücklich. Die Aufgabe besteht darin, daraus ein abgestimmtes Zielsystem und eine passende strategische Richtung zu entwickeln.\"}, {\"value\": \"B\", \"label\": \"2,4 Millionen Euro Umsatz, genau 600.000 Euro Investition und 15 Prozent Verderbquote.\", \"feedback\": \"Christian nennt diese drei Jahresziele ausdrücklich. Die Aufgabe besteht darin, daraus ein abgestimmtes Zielsystem und eine passende strategische Richtung zu entwickeln.\"}, {\"value\": \"C\", \"label\": \"900.000 Euro Umsatz, 2,64 Millionen Euro Werbebudget und 48 Prozent Verderbquote.\", \"feedback\": \"Christian nennt diese drei Jahresziele ausdrücklich. Die Aufgabe besteht darin, daraus ein abgestimmtes Zielsystem und eine passende strategische Richtung zu entwickeln.\"}, {\"value\": \"D\", \"label\": \"12.000 Euro Umsatz, mindestens 150.000 Euro Abschriften und keine Verderbgrenze.\", \"feedback\": \"Christian nennt diese drei Jahresziele ausdrücklich. Die Aufgabe besteht darin, daraus ein abgestimmtes Zielsystem und eine passende strategische Richtung zu entwickeln.\"}, {\"value\": \"E\", \"label\": \"600.000 Euro Umsatz, mindestens 2,4 Millionen Euro Personalaufwand und 10 Prozent Verderbquote.\", \"feedback\": \"Christian nennt diese drei Jahresziele ausdrücklich. Die Aufgabe besteht darin, daraus ein abgestimmtes Zielsystem und eine passende strategische Richtung zu entwickeln.\"}, {\"value\": \"F\", \"label\": \"Ein beliebiger Umsatz, unbegrenzte Werbeausgaben und ein vollständiger Verzicht auf Qualitätsziele.\", \"feedback\": \"Christian nennt diese drei Jahresziele ausdrücklich. Die Aufgabe besteht darin, daraus ein abgestimmtes Zielsystem und eine passende strategische Richtung zu entwickeln.\"}], \"correct\": \"A\"}, {\"id\": \"situation-3\", \"title\": \"Alunas Einwand\", \"question\": \"Welche Folgen zusätzlicher Varianten hebt Aluna hervor?\", \"options\": [{\"value\": \"A\", \"label\": \"Dass dadurch jede bisherige Kostenposition automatisch entfällt.\", \"feedback\": \"Aluna bringt die Auswirkungen auf Lagerung, Produktionslose und Transport ein. Diese Ressourcenfragen gehören zur Entscheidung über die Wachstumsrichtung.\"}, {\"value\": \"B\", \"label\": \"Dass neue Varianten grundsätzlich ohne Verpackung verkauft werden.\", \"feedback\": \"Aluna bringt die Auswirkungen auf Lagerung, Produktionslose und Transport ein. Diese Ressourcenfragen gehören zur Entscheidung über die Wachstumsrichtung.\"}, {\"value\": \"C\", \"label\": \"Zusätzliche Lagerplätze, kleinere Produktionslose und aufwendigere Kühltransporte.\", \"feedback\": \"Aluna bringt die Auswirkungen auf Lagerung, Produktionslose und Transport ein. Diese Ressourcenfragen gehören zur Entscheidung über die Wachstumsrichtung.\"}, {\"value\": \"D\", \"label\": \"Dass der niederländische Markt automatisch alle zusätzlichen Mengen abnimmt.\", \"feedback\": \"Aluna bringt die Auswirkungen auf Lagerung, Produktionslose und Transport ein. Diese Ressourcenfragen gehören zur Entscheidung über die Wachstumsrichtung.\"}, {\"value\": \"E\", \"label\": \"Dass eine Variante immer die gesamte bisherige Produktion ersetzt.\", \"feedback\": \"Aluna bringt die Auswirkungen auf Lagerung, Produktionslose und Transport ein. Diese Ressourcenfragen gehören zur Entscheidung über die Wachstumsrichtung.\"}, {\"value\": \"F\", \"label\": \"Dass mehr Varianten zwingend weniger Abstimmung und keine Planung benötigen.\", \"feedback\": \"Aluna bringt die Auswirkungen auf Lagerung, Produktionslose und Transport ein. Diese Ressourcenfragen gehören zur Entscheidung über die Wachstumsrichtung.\"}], \"correct\": \"C\"}, {\"id\": \"situation-4\", \"title\": \"Niederländischer Markt\", \"question\": \"Was ist zum niederländischen Händler bereits bekannt?\", \"options\": [{\"value\": \"A\", \"label\": \"Er hat die flächendeckende Vermarktung bereits verbindlich abgeschlossen.\", \"feedback\": \"Es liegt Interesse an einem Test vor. Die Handlungssituation verlangt ausdrücklich eine Entscheidung darüber, was im Pilotjahr noch nicht begonnen werden sollte.\"}, {\"value\": \"B\", \"label\": \"Er verlangt den sofortigen Rückzug aus dem norddeutschen Markt.\", \"feedback\": \"Es liegt Interesse an einem Test vor. Die Handlungssituation verlangt ausdrücklich eine Entscheidung darüber, was im Pilotjahr noch nicht begonnen werden sollte.\"}, {\"value\": \"C\", \"label\": \"Er übernimmt automatisch sämtliche Kosten neuer Produktvarianten.\", \"feedback\": \"Es liegt Interesse an einem Test vor. Die Handlungssituation verlangt ausdrücklich eine Entscheidung darüber, was im Pilotjahr noch nicht begonnen werden sollte.\"}, {\"value\": \"D\", \"label\": \"Er hat sämtliche Forschungsfragen bereits repräsentativ beantwortet.\", \"feedback\": \"Es liegt Interesse an einem Test vor. Die Handlungssituation verlangt ausdrücklich eine Entscheidung darüber, was im Pilotjahr noch nicht begonnen werden sollte.\"}, {\"value\": \"E\", \"label\": \"Er hat den gesamten Vorstand von BioCasa ersetzt.\", \"feedback\": \"Es liegt Interesse an einem Test vor. Die Handlungssituation verlangt ausdrücklich eine Entscheidung darüber, was im Pilotjahr noch nicht begonnen werden sollte.\"}, {\"value\": \"F\", \"label\": \"Er interessiert sich für einen Test; Julia möchte die Chance nutzen, aber keinen unvorbereiteten Rollout versprechen.\", \"feedback\": \"Es liegt Interesse an einem Test vor. Die Handlungssituation verlangt ausdrücklich eine Entscheidung darüber, was im Pilotjahr noch nicht begonnen werden sollte.\"}], \"correct\": \"F\"}, {\"id\": \"situation-5\", \"title\": \"Strategieauftrag\", \"question\": \"Welche Vorlage erwartet der Vorstand von Ihrem Team?\", \"options\": [{\"value\": \"A\", \"label\": \"Eine Sammlung unverbindlicher Wünsche ohne Messgrößen.\", \"feedback\": \"Das Team soll eine entscheidungsfähige strategische Beschlussvorlage erstellen. Die konkrete Ausarbeitung von Rezeptur, Preisen und Werbemitteln folgt später.\"}, {\"value\": \"B\", \"label\": \"Ausschließlich einen bereits druckfertigen Werbeprospekt.\", \"feedback\": \"Das Team soll eine entscheidungsfähige strategische Beschlussvorlage erstellen. Die konkrete Ausarbeitung von Rezeptur, Preisen und Werbemitteln folgt später.\"}, {\"value\": \"C\", \"label\": \"Nur einen neuen Pizzanamen ohne Bezug zur Unternehmenslage.\", \"feedback\": \"Das Team soll eine entscheidungsfähige strategische Beschlussvorlage erstellen. Die konkrete Ausarbeitung von Rezeptur, Preisen und Werbemitteln folgt später.\"}, {\"value\": \"D\", \"label\": \"Messbare Ziele und eine begründete Verbindung von Zielkunden, Wettbewerbsvorteil sowie Produkten und Märkten.\", \"feedback\": \"Das Team soll eine entscheidungsfähige strategische Beschlussvorlage erstellen. Die konkrete Ausarbeitung von Rezeptur, Preisen und Werbemitteln folgt später.\"}, {\"value\": \"E\", \"label\": \"Eine endgültige Rezeptur, ohne die strategische Richtung zu klären.\", \"feedback\": \"Das Team soll eine entscheidungsfähige strategische Beschlussvorlage erstellen. Die konkrete Ausarbeitung von Rezeptur, Preisen und Werbemitteln folgt später.\"}, {\"value\": \"F\", \"label\": \"Eine ungeprüfte Zusage, alle Kundengruppen gleichzeitig zu bedienen.\", \"feedback\": \"Das Team soll eine entscheidungsfähige strategische Beschlussvorlage erstellen. Die konkrete Ausarbeitung von Rezeptur, Preisen und Werbemitteln folgt später.\"}], \"correct\": \"D\"}]</script></section>","informieren.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Informieren</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"task-card phase-mode\" data-mode-panel=\"1\" data-phase=\"informieren\"><h2 class=\"phase-mode-title\">A · Stark geführt / tradiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 25 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit (Empfehlung)</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"0:1:1\" data-task-signature=\"c08f98b9\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit (Empfehlung)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit (Empfehlung)</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Lesen</strong> Sie M1/M2 und markieren Sie Rahmenziele, vorhandene Hinweise und begrenzte Ressourcen in drei Farben. <strong class=\"operator\">Ordnen</strong> Sie mit der Lehrkraft die Aussagen „Umsatz steigern“, „Pizza entwickeln“ und „Qualität als Kaufgrund stärken“ den Kategorien Ziel, Maßnahme und strategische Richtung zu. <strong class=\"operator\">Erschließen</strong> Sie danach M4 nach der festen Reihenfolge Wettbewerb – Zielgruppe – Produkt/Markt.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Marketing – Aufgaben </span>S. 59 und <span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61.</span></p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"25\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 25 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"0:1:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"2\" data-phase=\"informieren\"><h2 class=\"phase-mode-title\">B · Geführt mit Wahlstellen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 25 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><span><strong>Arbeitsform:</strong> Partnerarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"0:2:1\" data-task-signature=\"874bdb87\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"pair\" title=\"Partnerarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><small>Partnerarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erschließen</strong> Sie M1–M4 in Tandems und unterscheiden Sie Ziele, Maßnahmen und Strategieentscheidungen anhand eigener BioCasa-Beispiele. <strong class=\"operator\">Wählen</strong> Sie eine Tabelle oder ein beschriftetes Schaubild zur Verbindung der drei Strategieebenen.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61, <span class=\"book-keyword\">Undifferenzierte Marktbearbeitungsstrategie </span>S. 66 und <span class=\"book-keyword\">Differenzierte / konzentrierte / kundenindividuelle Marktbearbeitungsstrategie </span>S. 67.</span></p>\n<p><strong class=\"operator\">Halten</strong> Sie aus M2 einen tragfähigen Zielgruppenhinweis und eine wichtige Datengrenze fest.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"25\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 25 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"0:2:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"3\" data-phase=\"informieren\"><h2 class=\"phase-mode-title\">C · Mittelweg / teiloffen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 25 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"7\" r=\"3\"></circle><path d=\"M2 22v-5a6 6 0 0 1 12 0v5M18 3l1.2 2.5 2.8.4-2 2 .5 2.8-2.5-1.3-2.5 1.3.5-2.8-2-2 2.8-.4z\"></path></svg><span><strong>Arbeitsform:</strong> Expertengruppen und Austausch in der Stammgruppe</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"0:3:1\" data-task-signature=\"c28d1f80\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"expert-group\" title=\"Expertengruppen und Austausch in der Stammgruppe\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"7\" r=\"3\"></circle><path d=\"M2 22v-5a6 6 0 0 1 12 0v5M18 3l1.2 2.5 2.8.4-2 2 .5 2.8-2.5-1.3-2.5 1.3.5-2.8-2-2 2.8-.4z\"></path></svg><small>Expertengruppen und Austausch in der Stammgruppe</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Organisieren</strong> Sie ein kurzes Gruppenpuzzle zu M3/M4: Expertinnen und Experten für Ziele, Wettbewerb sowie Markt-/Produktwahl erklären ihre Perspektive anschließend in der Stammgruppe. Beziehen Sie die Forschungsgrenzen M2 in Ihre Erklärung ein.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\">je nach Expertise S. 59, S. 61, S. 67 oder S. 71/S. 72.</span></p>\n<p><strong class=\"operator\">Sichern</strong> Sie gemeinsam, warum die Modelle unterschiedliche Teile derselben Entscheidung bearbeiten.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"25\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 25 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"0:3:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"4\" data-phase=\"informieren\"><h2 class=\"phase-mode-title\">D · Weitgehend selbstgesteuert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 25 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit (Empfehlung)</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"0:4:1\" data-task-signature=\"d68d3e4d\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit (Empfehlung)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit (Empfehlung)</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Übernehmen</strong> Sie den Vorstandsauftrag und bestimmen Sie selbst die entscheidungsrelevanten Informationen aus M1/M2. Diagnostizieren Sie Ihre Sicherheit bei Zielmessung, Wettbewerbsvorteilen und Produkt-Markt-Zuordnung; schließen Sie Lücken mit M3/M4.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Marketing – Aufgaben </span>S. 59, <span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61 sowie <span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71/<span class=\"book-keyword\">Marktentwicklung / Produktentwicklung / Diversifikation </span>S. 72.</span></p>\n<p><strong class=\"operator\">Formulieren</strong> Sie ein vorläufiges strategisches Problem, das über „mehr verkaufen“ hinausgeht.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"25\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 25 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"0:4:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"5\" data-phase=\"informieren\"><h2 class=\"phase-mode-title\">E · Löppt – selbstgesteuert und selbstorganisiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 25 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"0:5:1\" data-task-signature=\"f0cb5ce8\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p>Klären Sie als Strategieteam selbst, worin die eigentliche Entscheidung des Vorstands liegt und welche Annahmen Ihre erste Einschätzung prägen. <strong class=\"operator\">Erschließen</strong> Sie M1–M4 bedarfsbezogen und prüfen Sie Begriffe gegenseitig.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Marketing – Aufgaben </span>S. 59 und <span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61.</span></p>\n<p><strong class=\"operator\">Notieren</strong> Sie Wissenslücken und wählen Sie selbst, wie und mit wem Sie diese schließen.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"25\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 25 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"0:5:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section>","planen.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Planen</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"task-card phase-mode\" data-mode-panel=\"1\" data-phase=\"planen\"><h2 class=\"phase-mode-title\">A · Stark geführt / tradiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Vierergruppe</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"1:1:1\" data-task-signature=\"2b5792e8\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Vierergruppe\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Vierergruppe</small></span><div class=\"assignment-body\"><p>Verteilen Sie im Viererteam die Rollen Finanzen, Küche, Logistik und Marketing aus M1. <strong class=\"operator\">Füllen</strong> Sie das Gerüst M6 zunächst mit den drei Rahmenzielen und einem selbst gewählten psychologischen Marketingziel aus; nutzen Sie M3 zur Messbarkeit. Die Lehrkraft gibt die Vergleichskriterien Kundenpassung, Ressourcenbedarf, Leitbild und Risiko vor; planen Sie damit den Vergleich der Bündel M5.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"1:1:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"2\" data-phase=\"planen\"><h2 class=\"phase-mode-title\">B · Geführt mit Wahlstellen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><span><strong>Arbeitsform:</strong> Partnerarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"1:2:1\" data-task-signature=\"0aabb32d\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"pair\" title=\"Partnerarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><small>Partnerarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Planen</strong> Sie die Beschlussvorlage mit den festen Bausteinen aus M6; wählen Sie eigene Verantwortlichkeiten und ein analoges oder digitales Format. Bestimmen Sie vier Vergleichskriterien und gewichten Sie diese, bevor Sie Bündel bewerten. <strong class=\"operator\">Skizzieren</strong> Sie ein viertes Marketingziel zusätzlich zu den drei Rahmenzielen und planen Sie dessen Messverfahren.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"1:2:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"3\" data-phase=\"planen\"><h2 class=\"phase-mode-title\">C · Mittelweg / teiloffen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"1:3:1\" data-task-signature=\"ad4eb9eb\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Planen</strong> Sie selbst den Weg zu den verbindlichen Meilensteinen Zielsystem und beschlussfähige Strategie. <strong class=\"operator\">Wählen</strong> Sie Rollen, Reihenfolge und Werkzeug; legen Sie vor der Bewertung gemeinsame Kriterien fest. Konstruieren Sie mindestens zwei in sich stimmige Bündel, die tatsächlich unterschiedliche Schwerpunktentscheidungen enthalten.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"1:3:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"4\" data-phase=\"planen\"><h2 class=\"phase-mode-title\">D · Weitgehend selbstgesteuert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit mit selbst gewählter Arbeitsteilung</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"1:4:1\" data-task-signature=\"2aa95b5b\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit mit selbst gewählter Arbeitsteilung\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit mit selbst gewählter Arbeitsteilung</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Planen</strong> Sie Aufgabenverteilung, Zeit und Darstellungsform selbst. Vereinbaren Sie einen Coach-Check, sobald Ihre Alternativen vollständig vergleichbar sind, und einen nach der Zielprüfung. <strong class=\"operator\">Definieren</strong> Sie vorher Kriterien und Ausschlussgründe; das Endprodukt muss sämtliche Pflichtnachweise enthalten.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"1:4:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"5\" data-phase=\"planen\"><h2 class=\"phase-mode-title\">E · Löppt – selbstgesteuert und selbstorganisiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit mit selbst gewählter Arbeitsteilung</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"1:5:1\" data-task-signature=\"30c0ecfe\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit mit selbst gewählter Arbeitsteilung\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit mit selbst gewählter Arbeitsteilung</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Organisieren</strong> Sie eine Lernumgebung für konzentrierte Quellenarbeit und eine kurze kontroverse Vorstandssitzung. Bestimmen Sie selbst Rollen, Methoden, sichtbare Arbeitsstände und eine Hilferufregel, beispielsweise wenn zwei Ziele gleichzeitig unerreichbar erscheinen. <strong class=\"operator\">Planen</strong> Sie die sechs Phasen und einen unabhängigen Qualitätscheck innerhalb der 180 Minuten.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"1:5:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section>","entscheiden.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Entscheiden</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"task-card phase-mode\" data-mode-panel=\"1\" data-phase=\"entscheiden\"><h2 class=\"phase-mode-title\">A · Stark geführt / tradiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Vierergruppe</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"2:1:1\" data-task-signature=\"c78165fb\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Vierergruppe\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Vierergruppe</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Wählen</strong> Sie nach der Rollenrunde ein vorrangiges Kundensegment und legen Sie dessen drei unterscheidende Merkmale fest. <strong class=\"operator\">Vergleichen</strong> Sie mindestens zwei vollständige Bündel, statt einzelne Modelle gegeneinander auszuspielen. <strong class=\"operator\">Halten</strong> Sie vorläufig fest, welches Ziel bei einem Konflikt als Grenze gilt und welche Entscheidung erst durch einen Pilot überprüft werden soll.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"2:1:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"2\" data-phase=\"entscheiden\"><h2 class=\"phase-mode-title\">B · Geführt mit Wahlstellen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><span><strong>Arbeitsform:</strong> Partnerarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"2:2:1\" data-task-signature=\"be9083a3\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"pair\" title=\"Partnerarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><small>Partnerarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Entscheiden</strong> Sie sich begründet für ein Segment und vergleichen Sie ein Bündel aus M5 mit einer selbst angepassten Alternative. <strong class=\"operator\">Legen</strong> Sie fest, welche Ressourcenbegrenzung Ihre Entscheidung besonders prägt. <strong class=\"operator\">Überprüfen</strong> Sie die vorläufige Kombination an M4, bevor Sie Einzelmaßnahmen formulieren.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"2:2:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"3\" data-phase=\"entscheiden\"><h2 class=\"phase-mode-title\">C · Mittelweg / teiloffen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"2:3:1\" data-task-signature=\"4cb51376\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p>Wägen Sie zwei Zielgruppen anhand M2 und der betrieblichen Ressourcen ab. <strong class=\"operator\">Entscheiden</strong> Sie sich für eine Priorität und halten Sie fest, welche Kundengruppe deshalb zunächst weniger intensiv bearbeitet wird. Treffen Sie einen vorläufigen Strategiebeschluss einschließlich einer fachlich begründeten Rückfalloption, falls der Pilot die Annahmen nicht bestätigt.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"2:3:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"4\" data-phase=\"entscheiden\"><h2 class=\"phase-mode-title\">D · Weitgehend selbstgesteuert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"2:4:1\" data-task-signature=\"15d68674\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Entwickeln</strong> Sie zwei Bündel mit plausiblen Zielgruppen und diskutieren Sie gezielt die stärkste Gegenposition zu Ihrem Favoriten. <strong class=\"operator\">Entscheiden</strong> Sie nach dem ersten Coach-Check selbst über Schwerpunkt, zurückgestellte Aktivität und Anpassungsregel. <strong class=\"operator\">Nutzen</strong> Sie zur Schärfung der Segmentwahl <img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\" title=\"Lehrbuch\"> <span class=\"book-keyword\">Undifferenzierte Marktbearbeitungsstrategie </span>S. 66 und <span class=\"book-keyword\">Differenzierte / konzentrierte / kundenindividuelle Marktbearbeitungsstrategie </span>S. 67.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"2:4:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"5\" data-phase=\"entscheiden\"><h2 class=\"phase-mode-title\">E · Löppt – selbstgesteuert und selbstorganisiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 20 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"2:5:1\" data-task-signature=\"1d6bf2a5\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p>Entwickeln und vergleichen Sie mindestens zwei vollständige Bündel; entscheiden Sie vor der Bewertung über Kriterien und deren Bedeutung. <strong class=\"operator\">Wählen</strong> Sie Zielsegment und strategische Richtung einschließlich einer bewusst zurückgestellten Option. <strong class=\"operator\">Prüfen</strong> Sie Ihre Marktbearbeitung anhand <img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\" title=\"Lehrbuch\"> <span class=\"book-keyword\">Undifferenzierte Marktbearbeitungsstrategie </span>S. 66 und <span class=\"book-keyword\">Differenzierte / konzentrierte / kundenindividuelle Marktbearbeitungsstrategie </span>S. 67 und dokumentieren Sie auch eine nachvollziehbare Minderheitsposition.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"20\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 20 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"2:5:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section>","durchfuehren.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Durchführen</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"task-card phase-mode\" data-mode-panel=\"1\" data-phase=\"durchfuehren\"><h2 class=\"phase-mode-title\">A · Stark geführt / tradiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 70 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Vierergruppe</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"3:1:1\" data-task-signature=\"3c56f332\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Vierergruppe\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Vierergruppe</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Arbeiten</strong> Sie nacheinander Zielmatrix, Strategievergleich und Beschlussvorlage M6 aus. <strong class=\"operator\">Prüfen</strong> Sie für jede gewählte Wachstumsrichtung ausdrücklich, ob Produkt und Markt für BioCasa neu oder bereits vorhanden sind.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71 und <span class=\"book-keyword\">Marktentwicklung / Produktentwicklung / Diversifikation </span>S. 72.</span></p>\n<p><strong class=\"operator\">Formulieren</strong> Sie vier vollständige Ziele, mindestens zwei Zielbeziehungen, zwei Umsetzungsfolgen und eine konkrete Anpassungsregel; die Lehrkraft prüft nach der Zielmatrix einen Zwischenstand.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"70\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 70 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"3:1:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"2\" data-phase=\"durchfuehren\"><h2 class=\"phase-mode-title\">B · Geführt mit Wahlstellen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 70 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><span><strong>Arbeitsform:</strong> Partnerarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"3:2:1\" data-task-signature=\"d6db1f26\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"pair\" title=\"Partnerarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><small>Partnerarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erstellen</strong> Sie die vier Ziele einschließlich Zuständigkeit, Messung und Zeitbezug; formulieren Sie mindestens zwei Zielbeziehungen. <strong class=\"operator\">Stellen</strong> Sie die Strategiealternativen nach denselben Kriterien gegenüber und schreiben Sie die Beschlussempfehlung. <strong class=\"operator\">Ordnen</strong> Sie den Niederlande-Piloten sowie eine neue Pizza getrennt in Ansoff ein.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71 und <span class=\"book-keyword\">Marktentwicklung / Produktentwicklung / Diversifikation </span>S. 72.</span></p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"70\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 70 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"3:2:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"3\" data-phase=\"durchfuehren\"><h2 class=\"phase-mode-title\">C · Mittelweg / teiloffen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 70 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"3:3:1\" data-task-signature=\"35884ba7\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Entwickeln</strong> Sie vier überprüfbare Ziele mit Verantwortung und Messverfahren; zeigen Sie mindestens zwei Zielbeziehungen. Schreiben Sie eine Beschlussvorlage, in der Wettbewerbsvorteil, Marktbearbeitung und Wachstum sichtbar aufeinander aufbauen.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61, <span class=\"book-keyword\">Undifferenzierte Marktbearbeitungsstrategie </span>S. 66/<span class=\"book-keyword\">Differenzierte / konzentrierte / kundenindividuelle Marktbearbeitungsstrategie </span>S. 67 und <span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71/<span class=\"book-keyword\">Marktentwicklung / Produktentwicklung / Diversifikation </span>S. 72.</span></p>\n<p>Ableitungen müssen jeweils an eine Information aus M1 oder M2 anknüpfen.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"70\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 70 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"3:3:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"4\" data-phase=\"durchfuehren\"><h2 class=\"phase-mode-title\">D · Weitgehend selbstgesteuert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 70 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit mit selbst gewählter Arbeitsteilung</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"3:4:1\" data-task-signature=\"48df671a\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit mit selbst gewählter Arbeitsteilung\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit mit selbst gewählter Arbeitsteilung</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erstellen</strong> Sie das Zielsystem und die Beschlussvorlage eigenständig. <strong class=\"operator\">Prüfen</strong> Sie alle Wachstumsmaßnahmen mit einer eigenen Produkt-Markt-Tabelle, statt nur Strategiebezeichnungen zu nennen.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71 und <span class=\"book-keyword\">Marktentwicklung / Produktentwicklung / Diversifikation </span>S. 72.</span></p>\n<p>Machen Sie die Auswirkungen auf Produktentwicklung und Kühlkette sowie die Grenzen Ihrer Befragungsgrundlage sichtbar.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"70\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 70 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"3:4:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"5\" data-phase=\"durchfuehren\"><h2 class=\"phase-mode-title\">E · Löppt – selbstgesteuert und selbstorganisiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 70 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><span><strong>Arbeitsform:</strong> Gruppenarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"3:5:1\" data-task-signature=\"92c87cd4\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"group\" title=\"Gruppenarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5\" r=\"3\"></circle><circle cx=\"4\" cy=\"9\" r=\"2\"></circle><circle cx=\"20\" cy=\"9\" r=\"2\"></circle><path d=\"M6 22v-5a6 6 0 0 1 12 0v5M1 21v-6a3 3 0 0 1 4-3M23 21v-6a3 3 0 0 0-4-3\"></path></svg><small>Gruppenarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Führen</strong> Sie Ihre Arbeit zu einer beschlussfähigen Vorlage mit vier SMART-Zielen, Messverantwortung, Zielbeziehungen und konkreten Folgen zusammen. <strong class=\"operator\">Nutzen</strong> Sie für die Wachstumszuordnung <img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\" title=\"Lehrbuch\"> <span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71 und <span class=\"book-keyword\">Marktentwicklung / Produktentwicklung / Diversifikation </span>S. 72 und kennzeichnen Sie, was im Szenario bestehender bzw. neuer Markt ist. <strong class=\"operator\">Organisieren</strong> Sie einen kurzen Perspektivwechsel, in dem ein Teammitglied die Empfehlung aus Sicht der Logistik bestreitet.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"70\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 70 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"3:5:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section>","bewerten.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Überprüfen</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"task-card phase-mode\" data-mode-panel=\"1\" data-phase=\"bewerten\"><h2 class=\"phase-mode-title\">A · Stark geführt / tradiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 30 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><span><strong>Arbeitsform:</strong> Eigene Arbeit und Gegenprüfung durch ein anderes Team</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"4:1:1\" data-task-signature=\"35d7bcfb\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"partner-groups\" title=\"Eigene Arbeit und Gegenprüfung durch ein anderes Team\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><small>Eigene Arbeit und Gegenprüfung durch ein anderes Team</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Tauschen</strong> Sie Ihre Vorlage mit einem anderen Team und prüfen Sie die Leitfragen in M6. <strong class=\"operator\">Kontrollieren</strong> Sie besonders, ob Ihr angestrebter Qualitätsvorteil zu Marktbearbeitung und Kapazität passt und ob „Nische“ fälschlich nur aus einem kleinen Marktanteil abgeleitet wurde.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Undifferenzierte Marktbearbeitungsstrategie </span>S. 66 und <span class=\"book-keyword\">Differenzierte / konzentrierte / kundenindividuelle Marktbearbeitungsstrategie </span>S. 67.</span></p>\n<p>Überarbeiten Sie mindestens eine Aussage, deren Messung oder Begründung noch unklar ist.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"30\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 30 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"4:1:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"2\" data-phase=\"bewerten\"><h2 class=\"phase-mode-title\">B · Geführt mit Wahlstellen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 30 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><span><strong>Arbeitsform:</strong> Partnerarbeit und Gegenprüfung durch ein anderes Zweierteam</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"4:2:1\" data-task-signature=\"73805bd7\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"partner-groups\" title=\"Partnerarbeit und Gegenprüfung durch ein anderes Zweierteam\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><small>Partnerarbeit und Gegenprüfung durch ein anderes Zweierteam</small></span><div class=\"assignment-body\"><p>Lassen Sie ein anderes Tandem die Zielmessung und den Zusammenhang zwischen Wettbewerbsvorteil und Zielgruppe prüfen. <strong class=\"operator\">Bearbeiten</strong> Sie den Einwand „Bei nur 9 Prozent Marktanteil bei pflanzlichen Pizzen muss BioCasa automatisch eine Nischenstrategie wählen“ fachlich mit M4.</p>\n<p class=\"book-line\"><img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\"><span class=\"book-reference\"><span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61 und <span class=\"book-keyword\">Differenzierte / konzentrierte / kundenindividuelle Marktbearbeitungsstrategie </span>S. 67.</span></p>\n<p><strong class=\"operator\">Kontrollieren</strong> Sie anschließend Ihre Anpassungsregel auf einen beobachtbaren Auslöser.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"30\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 30 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"4:2:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"3\" data-phase=\"bewerten\"><h2 class=\"phase-mode-title\">C · Mittelweg / teiloffen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 30 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><span><strong>Arbeitsform:</strong> Eigene Arbeit und Gegenprüfung durch ein anderes Team</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"4:3:1\" data-task-signature=\"36a275e0\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"partner-groups\" title=\"Eigene Arbeit und Gegenprüfung durch ein anderes Team\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><small>Eigene Arbeit und Gegenprüfung durch ein anderes Team</small></span><div class=\"assignment-body\"><p>Präsentieren Sie Ihre Vorlage einem anderen Team in einer kurzen Vorstandssimulation; dessen Mitglieder übernehmen je eine betriebliche Perspektive. <strong class=\"operator\">Prüfen</strong> Sie, ob das gewählte Marketingziel ein erwünschtes Ergebnis oder nur eine Tätigkeit beschreibt. <strong class=\"operator\">Nutzen</strong> Sie zur Korrektur der strategischen Begrifflichkeit <img class=\"book-ref-icon\" src=\"assets/lehrbuch-icon.png\" alt=\"Lehrbuch\" title=\"Lehrbuch\"> <span class=\"book-keyword\">Marketingstrategie / Kostenführerschaft / Wettbewerbsstrategie </span>S. 61 und <span class=\"book-keyword\">Produkt-Markt-Matrix / Marktdurchdringung </span>S. 71. <strong class=\"operator\">Halten</strong> Sie die wichtigste Veränderung nach dem Feedback fest.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"30\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 30 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"4:3:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"4\" data-phase=\"bewerten\"><h2 class=\"phase-mode-title\">D · Weitgehend selbstgesteuert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 30 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><span><strong>Arbeitsform:</strong> Gegencheck aus anderer Unternehmensperspektive und Coach-Gespräch</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"4:4:1\" data-task-signature=\"9c6c7c5d\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"partner-groups\" title=\"Gegencheck aus anderer Unternehmensperspektive und Coach-Gespräch\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"2\"></circle><circle cx=\"19\" cy=\"6\" r=\"2\"></circle><path d=\"M1 17v-3a4 4 0 0 1 8 0v3M15 17v-3a4 4 0 0 1 8 0v3M8 21h8M14 19l2 2-2 2M10 19l-2 2 2 2\"></path></svg><small>Gegencheck aus anderer Unternehmensperspektive und Coach-Gespräch</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Organisieren</strong> Sie einen Gegencheck aus einer anderen Unternehmensperspektive und prüfen Sie die rechnerische Umsatzveränderung, die Messbarkeit sowie alle Zielbeziehungen. Besprechen Sie mit dem Coach nur die strittigste Verbindung zwischen Ziel und Strategie. Geben Sie Ihre Vorlage erst frei, wenn eine verantwortliche Person und ein Termin für jede Zielkontrolle erkennbar sind.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"30\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 30 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"4:4:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"5\" data-phase=\"bewerten\"><h2 class=\"phase-mode-title\">E · Löppt – selbstgesteuert und selbstorganisiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 30 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><span><strong>Arbeitsform:</strong> Gegenprüfung mit selbst gewählter fachkundiger Person</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"4:5:1\" data-task-signature=\"8822f368\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"pair\" title=\"Gegenprüfung mit selbst gewählter fachkundiger Person\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"6\" r=\"3\"></circle><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><path d=\"M1 22v-5a6 6 0 0 1 12 0v5M15 22v-5a6 6 0 0 1 8-5\"></path></svg><small>Gegenprüfung mit selbst gewählter fachkundiger Person</small></span><div class=\"assignment-body\"><p>Bestimmen Sie selbst einen fachkundigen Gegenleser und geben Sie ihm prüfbare Kriterien statt einer bloßen Bitte um Zustimmung. <strong class=\"operator\">Kontrollieren</strong> Sie Datenbezug, logischen Zusammenhang der drei Strategieebenen und beobachtbare Anpassungsauslöser. <strong class=\"operator\">Entscheiden</strong> Sie eigenverantwortlich über Korrekturen und halten Sie fest, welche Restunsicherheit der Vorstand mitbeschließen muss.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"30\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 30 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"4:5:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section>","reflektieren.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Reflektieren</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><section class=\"task-card phase-mode\" data-mode-panel=\"1\" data-phase=\"reflektieren\"><h2 class=\"phase-mode-title\">A · Stark geführt / tradiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 15 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit (Empfehlung)</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"5:1:1\" data-task-signature=\"4254bae3\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit (Empfehlung)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit (Empfehlung)</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erklären</strong> Sie ohne KI in drei Sätzen, welche verschiedenen Fragen Porter, Marktsegmentierung und Ansoff beantworten. Nennen Sie außerdem einen Konflikt zwischen Wachstum und Verderb, den Ihr Zielsystem noch nicht automatisch löst. <strong class=\"operator\">Beschreiben</strong> Sie, welche Information Sie beim nächsten Vorstandstermin dafür benötigen.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"15\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 15 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"5:1:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"2\" data-phase=\"reflektieren\"><h2 class=\"phase-mode-title\">B · Geführt mit Wahlstellen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 15 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"5:2:1\" data-task-signature=\"377251de\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erläutern</strong> Sie individuell ohne KI, warum neue Produkte für neue Märkte eine andere Entscheidung sind als bestehende Produkte in einem neuen Absatzland. <strong class=\"operator\">Benennen</strong> Sie eine selbst getroffene Wahl, die Ihre Vorlage verbessert hat, und eine verbleibende Unsicherheit. Geben Sie an, wie diese Unsicherheit im Pilotjahr überprüft werden kann.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"15\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 15 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"5:2:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"3\" data-phase=\"reflektieren\"><h2 class=\"phase-mode-title\">C · Mittelweg / teiloffen</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 15 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit (Empfehlung)</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"5:3:1\" data-task-signature=\"b839a186\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit (Empfehlung)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit (Empfehlung)</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erläutern</strong> Sie ohne KI die Wirkung eines konkreten Zielkonflikts auf Ihre Beschlussempfehlung. <strong class=\"operator\">Benennen</strong> Sie anschließend, welches Gruppenpuzzle-Wissen Sie selbst zunächst nicht erklären konnten und nun sicherer anwenden. <strong class=\"operator\">Formulieren</strong> Sie einen eigenen nächsten Lernschritt.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"15\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 15 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"5:3:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"4\" data-phase=\"reflektieren\"><h2 class=\"phase-mode-title\">D · Weitgehend selbstgesteuert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 15 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"5:4:1\" data-task-signature=\"6539aefa\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit</small></span><div class=\"assignment-body\"><p><strong class=\"operator\">Erklären</strong> Sie individuell ohne KI, wie Ihr Bündel bei einem Verbot zusätzlicher Produktvarianten verändert werden müsste. <strong class=\"operator\">Begründen</strong> Sie die betroffene Ansoff-Richtung und nennen Sie eine weiterhin mögliche Maßnahme. <strong class=\"operator\">Beurteilen</strong> Sie, ob Ihre selbst geplanten Kontrollpunkte diese Art von Abhängigkeit rechtzeitig sichtbar machten.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"15\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 15 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"5:4:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><section class=\"task-card phase-mode\" data-mode-panel=\"5\" data-phase=\"reflektieren\"><h2 class=\"phase-mode-title\">E · Löppt – selbstgesteuert und selbstorganisiert</h2><div class=\"phase-meta\"><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg><span><strong>Arbeitszeit:</strong> 15 Minuten</span></p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><span><strong>Arbeitsform:</strong> Einzelarbeit</span></p></div><div class=\"task-text\"><article class=\"assignment-frame\" data-task-number=\"1\" data-goodnotes-task=\"true\" data-task-id=\"5:5:1\" data-task-signature=\"94f7a996\"><span class=\"assignment-number\" aria-label=\"Auftrag 1\">1</span><button type=\"button\" class=\"assignment-goodnotes-button\" data-share-workbook=\"\" aria-label=\"Arbeitsheft dieser Phase in GoodNotes importieren\"><img class=\"assignment-goodnotes\" src=\"assets/goodnotes.png\" alt=\"GoodNotes\"></button><span class=\"assignment-social\" data-workform=\"individual\" title=\"Einzelarbeit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"6\" r=\"3\"></circle><path d=\"M5 22v-4a7 7 0 0 1 14 0v4\"></path></svg><small>Einzelarbeit</small></span><div class=\"assignment-body\"><p>Beantworten Sie ohne KI individuell: „Warum sind Porter, Segmentierung und Ansoff in unserer Vorlage gleichzeitig nötig?“ <strong class=\"operator\">Beurteilen</strong> Sie dann, ob Ihre Teamorganisation sachlichen Widerspruch erleichtert oder erschwert hat. <strong class=\"operator\">Formulieren</strong> Sie eine konkrete Änderung für den nächsten selbstorganisierten Entscheidungsauftrag.</p>\n<span class=\"assignment-time\" data-time-ui=\"true\" data-minutes=\"15\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 6v6l4 2\"></path></svg> ca. 15 Min.</span></div><label class=\"task-completion no-print\" data-completion-label=\"\" contenteditable=\"false\"><input type=\"checkbox\" data-task-complete=\"\" data-task-id=\"5:5:1\" aria-label=\"Aufgabe 1 als erledigt markieren\" disabled=\"\"><span class=\"sr-only\">Aufgabe erledigt</span></label></article></div></section><div data-assessment-widget=\"\"></div>","m1.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M1 · Strategischer Datenraum und Vorstandsauftrag</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app acrobat\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>Adobe Acrobat Reader</strong><span class=\"file\">Strategischer Datenraum und Vorstandsauftrag</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Werkzeuge · Kommentieren · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 50%\">\n<col style=\"width: 50%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Ausgangslage / Rahmen</th>\n<th>Wert bzw. verbindliche Vorgabe</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Rechtsform / Größe</td>\n<td>Nicht börsennotierte BioCasa AG, 48 Beschäftigte, Produktion in Aurich</td>\n</tr>\n<tr class=\"even\">\n<td>Umsatz GJ05</td>\n<td>2.400.000 €; davon Klassik-Pizzen 900.000 €, Pflanzliche Pizzen 720.000 €, Spezial-Pizzen 540.000 €, Pizza-Kits 240.000 €</td>\n</tr>\n<tr class=\"odd\">\n<td>Umsatz-Rahmenziel GJ06</td>\n<td class=\"numeric-cell\">2.640.000 €</td>\n</tr>\n<tr class=\"even\">\n<td>Deckungsbeitrags-Rahmenziel GJ06</td>\n<td>Absoluter Jahres-Deckungsbeitrag mindestens 900.000 €</td>\n</tr>\n<tr class=\"odd\">\n<td>Verderbquote</td>\n<td>GJ05: 3,5 %; GJ06: höchstens 2,0 % der produzierten Menge; gleiche Mengenerfassung in beiden Jahren</td>\n</tr>\n<tr class=\"even\">\n<td>Erweiterungsgrenze im Pilot</td>\n<td>Höchstens zwei neue Varianten; keine zusätzliche Produktionshalle in GJ06</td>\n</tr>\n<tr class=\"odd\">\n<td>Niederlande</td>\n<td>Begrenzter Pilot, kein flächendeckender Rollout</td>\n</tr>\n<tr class=\"even\">\n<td>Leitbild</td>\n<td>Alltagstaugliche Bio-Pizzen, nachvollziehbare Herkunft, weniger Lebensmittelabfälle, faire Bedingungen, wirtschaftlich tragfähige Kühlkette</td>\n</tr>\n<tr class=\"odd\">\n<td>Positionierungsgrenze</td>\n<td>Qualität, Alltagstauglichkeit und Transparenz; keine Discountpositionierung</td>\n</tr>\n</tbody>\n</table>\n</div><p><strong>Erklärung Deckungsbeitrag:</strong> Umsatzerlöse minus variable Kosten. Der absolute Jahreswert ist ein strategisches Planungsziel; er wird hier weder als Gewinn noch als Monatsbetriebsergebnis behandelt. Eine vollständige Kostenrechnung folgt später.</p>\n<p><strong>Sortimentsabgrenzung:</strong> GJ05 umfasst 15 bestehende Produkte: fünf Klassik-Pizzen, vier rein pflanzliche Standardpizzen, vier Spezial-Pizzen mit besonderen Teigen/Formaten und zwei Pizza-Kits. Jede Variante ist genau einer Familie zugeordnet; Kits zählen mit ihrem Gesamtumsatz nur als Kit. Die Gartenpizza wäre eine zusätzliche Variante in GJ06.</p>\n<p><strong>Rollen:</strong> Christian Kannegießer verlangt wirtschaftlich tragfähiges Wachstum. Fari Yalcin verantwortet überzeugende Rezepturen und beherrschbare Varianten. Aluna Chengo fordert planbare Lose, möglichst geringe Abschriften und eine zuverlässige Kühlkette. Julia de Buhr verlangt ein verständliches Kundenversprechen und überprüfbare Marketingwirkungen.</p>\n</article></section></div></div>","m2.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M2 · Forschungs- und Marktbriefing für den isolierten Einstieg</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app acrobat\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>Adobe Acrobat Reader</strong><span class=\"file\">Forschungs- und Marktbriefing für den isolierten Einstieg</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Werkzeuge · Kommentieren · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><p>Bei einer freiwilligen Befragung wurden 240 vollständige Antworten erhoben: je 80 Pendelnde/Erwerbstätige, Familienhaushalte und Studierende. Die Gruppen wurden nicht proportional zur tatsächlichen Marktverteilung ausgewählt. Eine unkompliziert im Backofen zuzubereitende pflanzliche Pizza mit 400 g bevorzugten 60 Pendelnde, 32 Familienhaushalte und 44 Studierende; die übrigen Befragten wählten eine Familienpizza oder ein Pizza-Kit. Die Stichprobe ist nicht repräsentativ.</p>\n<div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 25%\">\n<col style=\"width: 25%\">\n<col style=\"width: 25%\">\n<col style=\"width: 25%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Segment</th>\n<th>Konkret zu prüfender Nutzen</th>\n<th>Erreichbarkeit im Szenario</th>\n<th>Begrenzung</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Pendelnde/Erwerbstätige in Norddeutschland</td>\n<td>Unkompliziertes Pizza-Abendessen zu Hause nach der Arbeit</td>\n<td>Bestehende Handelspartner am Wohnort oder auf dem Heimweg</td>\n<td>Tiefkühlaufbewahrung und geeigneter Backofen erforderlich; Vorheizen kommt zur Backzeit hinzu.</td>\n</tr>\n<tr class=\"even\">\n<td>Familienhaushalte in Norddeutschland</td>\n<td>Größere oder kombinierbare Portionen</td>\n<td>Bestehende Partner, gemeinsame Einkaufsplanung</td>\n<td>Eine Pizza mit 400 g reicht je nach Haushalt nicht für ein gemeinsames Essen; mehrere Stücke oder ein Familienformat sind zu prüfen.</td>\n</tr>\n<tr class=\"odd\">\n<td>Studierende in Norddeutschland</td>\n<td>Einfach zuzubereitende Pizza; bei Bedarf mit anderen Portionen kombinierbar</td>\n<td>Hochschulnahe Märkte als zusätzlicher Zugang</td>\n<td>Preisakzeptanz je Segment ist nicht erhoben.</td>\n</tr>\n</tbody>\n</table>\n</div><p>Von allen Befragten nannten 84 von 240 eine Preisobergrenze von mindestens 5,50 Euro für die 400-g-Pizza. Daraus lässt sich keine besondere Zahlungsbereitschaft einzelner Segmente und kein Absatzvolumen ableiten. Eine zusätzliche Erhebung muss Nutzungshürden und Kaufverhalten prüfen.</p>\n<p><strong>Messbasis für ein psychologisches Ziel:</strong> In einer separaten, gleichartig angelegten lokalen Passantenbefragung mit 200 Personen erkannten in GJ05 36 Personen die Marke gestützt, also nach Vorlage des Namens. Die Auswahl war keine Zufallsauswahl. Für eine interne Verlaufskontrolle soll in GJ06 dasselbe Standort-, Tageszeit- und Fragenverfahren wiederholt werden; die Kennzahl ist kein repräsentativer Bekanntheitswert für ganz Norddeutschland.</p>\n</article></section></div></div>","m3.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M3 · Ziele und Zielbeziehungen</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app onenote\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>OneNote</strong><span class=\"file\">Ziele und Zielbeziehungen</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Start · Einfügen · Zeichnen · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><p>Ein Ziel beschreibt einen angestrebten Zustand; eine Maßnahme beschreibt, was dafür getan wird. „Zwei Werbevideos veröffentlichen“ ist zunächst eine Tätigkeit. „Bis Ende GJ06 erreichen mindestens 50 von 200 Befragten im festgelegten lokalen Messverfahren gestützte Markenbekanntheit“ ist ein überprüfbares Wirkungsziel, dessen sachliche Angemessenheit noch zu begründen ist.</p>\n<p><strong>SMART-Prüfung:</strong> spezifischer Inhalt und Geltungsbereich; messbares Ausmaß mit Bezugsgröße; abgestimmte/akzeptierte Verantwortung; realistischer Bezug auf Ressourcen und Ausgangslage; Termin. Bei der Realistik reicht eine hübsche Zahl nicht: Benennen Sie mindestens eine Annahme und einen frühen Kontrolltermin. Ökonomische Ziele betreffen etwa Umsatz oder Deckungsbeitrag; psychologische Ziele etwa Bekanntheit, Vertrauen oder Präferenz. Ökologische und soziale Ziele können Marketingentscheidungen begrenzen und zugleich die Positionierung stützen.</p>\n<p><strong>Zielbeziehungen:</strong> Komplementäre Ziele unterstützen sich, konkurrierende Ziele behindern sich unter gegebenen Bedingungen, indifferente Ziele beeinflussen sich im betrachteten Zusammenhang nicht erkennbar. Höhere Verkäufe und weniger Verderb können sich unterstützen, wenn Bestellungen genauer planbar werden; zusätzliche Varianten können dagegen die Verderbquote erhöhen. Eine Beziehung ist begründungspflichtig und nicht für jede Maßnahme gleich.</p>\n<p><strong>Zu prüfen:</strong> „Wir werden bekannter.“ – „Bis Ende GJ06 liegt unser Umsatz bei 2.640.000 Euro.“ – „Wir sind bis zum Sommer Marktführer für sämtliche Tiefkühlpizzen.“ Die Formulierung allein beweist weder Akzeptanz noch Realistik.</p>\n</article></section></div></div>","m4.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M4 · Drei Strategieebenen, die zusammenwirken</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app onenote\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>OneNote</strong><span class=\"file\">Drei Strategieebenen, die zusammenwirken</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Start · Einfügen · Zeichnen · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 33%\">\n<col style=\"width: 33%\">\n<col style=\"width: 33%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Ebene</th>\n<th>Leitfrage</th>\n<th>Möglichkeiten und Grenzen</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Wettbewerb nach Porter</td>\n<td>Wodurch erzielen wir einen Vorteil gegenüber anderen?</td>\n<td><strong>Kostenführerschaft:</strong> struktureller Kostenvorteil, nicht bloß niedriger Verkaufspreis. <strong>Differenzierung:</strong> wahrnehmbarer, relevanter und belegbarer Zusatznutzen. <strong>Fokussierung:</strong> Konzentration auf einen engen Marktbereich; dort ebenfalls Kosten- oder Differenzierungsvorteil anstreben.</td>\n</tr>\n<tr class=\"even\">\n<td>Marktbearbeitung</td>\n<td>Welche Kundengruppen bedienen wir mit welchem Angebot?</td>\n<td><strong>Undifferenziert:</strong> ein weitgehend einheitliches Angebot. <strong>Differenziert:</strong> unterschiedliche Angebote für mehrere Segmente. <strong>Konzentriert:</strong> Schwerpunkt auf einem Segment. <strong>Kundenindividuell:</strong> Anpassung an einzelne Abnehmer; kann hohe Komplexität verursachen.</td>\n</tr>\n<tr class=\"odd\">\n<td>Wachstum nach Ansoff</td>\n<td>Sind Produkt und Markt für uns vorhanden oder neu?</td>\n<td>Vorhanden/vorhanden: Marktdurchdringung; vorhanden/neu: Marktentwicklung; neu/vorhanden: Produktentwicklung; neu/neu: Diversifikation. Die Einstufung hängt von der vorab definierten Marktgrenze ab.</td>\n</tr>\n</tbody>\n</table>\n</div><p><strong>Marktabgrenzung für diesen Fall:</strong> BioCasa bedient bereits norddeutsche Käufer alltagstauglicher Bio-Tiefkühlpizzen über vorhandene Handelspartner. Eine neu entwickelte Pizza für diesen Kundenmarkt zählt hier als Produktentwicklung. Bestehende Produkte in einem erstmals erschlossenen niederländischen Vertriebsmarkt bedeuten Marktentwicklung. Eine neue Pizza erstmals ausschließlich für einen neuen niederländischen Markt kombiniert neue Produkte und neue Märkte. Eine ausgearbeitete Strategie kann mehrere zeitlich geordnete Vorhaben enthalten; Risiken und Ressourcen sind je Vorhaben zu betrachten.</p>\n<p>Die drei Zeilen sind keine konkurrierenden Antwortmöglichkeiten. Eine fokussierte Differenzierung kann mit konzentrierter Marktbearbeitung und Produktentwicklung verbunden werden. Eine niedrige Umsatz- oder Marktanteilszahl beweist keine bewusste Nischenstrategie. Es gibt auch keine allgemeingültige Schwelle, ab der ein Unternehmen automatisch Marktführer, Herausforderer oder Nischenanbieter wird.</p>\n</article></section></div></div>","m5.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M5 · Diskussionsangebote, keine fertigen Beschlüsse</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app teams\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>Microsoft Teams</strong><span class=\"file\">Diskussionsangebote, keine fertigen Beschlüsse</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Beiträge · Dateien · Besprechungsnotizen</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 25%\">\n<col style=\"width: 25%\">\n<col style=\"width: 25%\">\n<col style=\"width: 25%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Bündel</th>\n<th>Wettbewerb / Kunden / Wachstum</th>\n<th>Attraktion</th>\n<th>Zu prüfender Konflikt</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Norddeutscher Alltagsschwerpunkt</td>\n<td>Differenzierung über Nutzen und Transparenz; zunächst konzentrierte Ansprache berufstätiger Käufer; eine neue Pizza im bestehenden Markt</td>\n<td>Überschaubares Lernfeld, an vorhandene Partner anschließbar</td>\n<td>Andere Bedürfnisse werden zunächst geringer bedient; Alltagstauglichkeit noch praktisch prüfen.</td>\n</tr>\n<tr class=\"even\">\n<td>Zwei Bedarfslinien</td>\n<td>Differenzierung; ausgewählte Bearbeitung von Berufstätigen und Familien; je eine angepasste Ausführung im bestehenden Markt</td>\n<td>Zwei deutliche Nutzungssituationen</td>\n<td>Grenze von zwei Varianten ausgeschöpft; Lose, Kommunikation und Bestände werden komplexer.</td>\n</tr>\n<tr class=\"odd\">\n<td>Export zuerst</td>\n<td>Differenzierung bestehender Produkte; konzentrierter Pilot bei wenigen niederländischen Partnern; Marktentwicklung</td>\n<td>Produktkenntnis kann genutzt werden</td>\n<td>Neue Kundschaft, Kennzeichnung, Absatzplanung und Kühlweg müssen geprüft werden; Lernkapazität fehlt eventuell für neue Varianten.</td>\n</tr>\n</tbody>\n</table>\n</div><p>Der Vorschlag „breit über niedrige Preise wachsen“ darf als verworfene Alternative geprüft werden. Ein Preisnachlass stellt für sich keine Kostenführerschaft her und muss mit Positionierung sowie Deckungsbeitragsziel abgeglichen werden. Sie dürfen eigene Mischungen entwickeln, müssen jedoch Prioritäten, Reihenfolge und Ressourcenkonflikte ausweisen.</p>\n</article></section></div></div>","m6.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M6 · Beschlussvorlage und Entscheidungsmatrix</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app onenote\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>OneNote</strong><span class=\"file\">Beschlussvorlage und Entscheidungsmatrix</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Start · Einfügen · Zeichnen · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><p><strong>Adressat:</strong> Vorstand BioCasa AG · <strong>Betreff:</strong> Strategische Schwerpunkte GJ06</p>\n<ol type=\"1\">\n<li>Entscheidung in höchstens fünf Sätzen, mit bewusst zurückgestellter Option.</li>\n<li>Zielsegment: mindestens drei Merkmale wie Nutzungssituation, geografischer Zugang und gewünschter Nutzen; keine unbelegten Persönlichkeitsklischees.</li>\n<li>Zielsystem:</li>\n</ol>\n<div class=\"table-scroll wide-data-table\" tabindex=\"0\" aria-label=\"Breite Tabelle – horizontal verschiebbar\"><table style=\"width:100%;\">\n<thead>\n<tr class=\"header\">\n<th>Ziel / Typ</th>\n<th>Ausgangswert</th>\n<th>Sollwert und Termin</th>\n<th>Messverfahren / Bezugsgröße</th>\n<th>Verantwortlich</th>\n<th>Früher Kontrollpunkt / Annahme</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Umsatz</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr class=\"even\">\n<td>Deckungsbeitrag</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr class=\"odd\">\n<td>Verderb</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr class=\"even\">\n<td>Eigenes Marketingziel</td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table>\n</div><p><strong>Datenhinweis:</strong> Ein Jahres-Deckungsbeitrag für GJ05 ist nicht angegeben. Tragen Sie beim Ausgangswert „nicht angegeben; im Controlling zu erheben“ ein, statt einen Wert zu erfinden. Das Mindestziel für GJ06 bleibt verbindlich.</p>\n<ol start=\"4\" type=\"1\">\n<li>Zwei erläuterte Zielbeziehungen; bei Konflikten Priorität und Ausgleich nennen.</li>\n<li>Zwei vollständige Bündel im Vergleich:</li>\n</ol>\n<div class=\"table-scroll\"><table style=\"width:100%;\">\n<colgroup>\n<col style=\"width: 23%\">\n<col style=\"width: 30%\">\n<col style=\"width: 23%\">\n<col style=\"width: 23%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Kriterium</th>\n<th style=\"text-align: right;\">Gewicht, zusammen 100 %</th>\n<th>Bündel 1: Befund und Urteil</th>\n<th>Bündel 2: Befund und Urteil</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Kundenpassung</td>\n<td style=\"text-align: right;\"></td>\n<td></td>\n<td></td>\n</tr>\n<tr class=\"even\">\n<td>Ressourcen</td>\n<td style=\"text-align: right;\"></td>\n<td></td>\n<td></td>\n</tr>\n<tr class=\"odd\">\n<td>Leitbild / Positionierung</td>\n<td style=\"text-align: right;\"></td>\n<td></td>\n<td></td>\n</tr>\n<tr class=\"even\">\n<td>Risiko / Lernmöglichkeit</td>\n<td style=\"text-align: right;\"></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table>\n</div><p>Ein Punktwert ersetzt keine Begründung. Ausschlussbedingungen müssen vor der Punktaddition geprüft werden.</p>\n<ol start=\"6\" type=\"1\">\n<li>Beschluss mit Porter-/Marktbearbeitungs-/Ansoff-Zuordnung, zwei konkreten Folgen und einer messbaren Anpassungsregel.</li>\n</ol>\n<p><strong>Freigabeprüfung:</strong> Sind vier Ziele messbar und terminiert? Sind die drei Rahmenziele vollständig enthalten? Wurde von 2.400.000 auf 2.640.000 Euro richtig gerechnet? Ist der Deckungsbeitrag nicht als Gewinn bezeichnet? Sind die drei Strategieebenen klar unterschieden und dennoch verbunden? Ist die Befragung als Hinweis, nicht als gesicherte Marktprognose verwendet? Ist die Konsequenz für Kapazität und Verderb erklärt?</p>\n</article></section></div></div>","m7.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M7 · Lehrbuch · Stichwörter und Seiten</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app acrobat\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>Adobe Acrobat Reader</strong><span class=\"file\">Lehrbuch · Stichwörter und Seiten</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Werkzeuge · Kommentieren · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><p><strong>Lehrbuch</strong></p>\n<div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 30%\">\n<col style=\"width: 40%\">\n<col style=\"width: 30%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Thema</th>\n<th style=\"text-align: right;\">Seite</th>\n<th>Verwendung</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Aufgaben des Marketings</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">59</td>\n<td>Ziele, Planung und Kundenorientierung einordnen</td>\n</tr>\n<tr class=\"even\">\n<td>Marketingstrategie, Kostenführerschaft, Differenzierung</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">61</td>\n<td>Wettbewerbsvorteil begründen</td>\n</tr>\n<tr class=\"odd\">\n<td>Undifferenzierte Marktbearbeitung</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">66</td>\n<td>Breites Standardangebot beurteilen</td>\n</tr>\n<tr class=\"even\">\n<td>Differenzierte, konzentrierte und kundenindividuelle Marktbearbeitung</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">67</td>\n<td>Zielgruppen und Ressourcen abgleichen</td>\n</tr>\n<tr class=\"odd\">\n<td>Produkt-Markt-Matrix, Marktdurchdringung</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">71</td>\n<td>Bestehende Produkte und Märkte abgrenzen</td>\n</tr>\n<tr class=\"even\">\n<td>Marktentwicklung, Produktentwicklung, Diversifikation</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">72</td>\n<td>Wachstumsvorhaben korrekt zuordnen</td>\n</tr>\n</tbody>\n</table>\n</div></article></section></div></div>","m8.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M8 · Ihr Auftrag im Überblick</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app onenote\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>OneNote</strong><span class=\"file\">Ihr Auftrag im Überblick</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Start · Einfügen · Zeichnen · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><p><strong>Lerngebiet:</strong> LG03 · <strong>Zeitrichtwert:</strong> 4 UE / 180 Minuten · <strong>Unternehmen:</strong> BioCasa AG, Aurich · <strong>Zeitpunkt:</strong> Strategieplanung GJ06. Alle Fallwerte sind didaktische Szenariodaten.</p>\n<p><strong>Ausgangslage:</strong> BioCasa ist eine nicht börsennotierte AG mit 48 Beschäftigten und produziert Bio-Tiefkühlpizzen und ergänzende Pizza-Kits für Norddeutschland. Ein begrenzter Niederlande-Pilot ist vorgesehen. M1 enthält die aktuelle wirtschaftliche Lage, M2 die benötigten Forschungsergebnisse als eigenständigen Auszug. Sie übernehmen die Rolle eines internen Strategieteams. Vorausgesetzt werden Prozentrechnung und das Unterscheiden von Ziel und Maßnahme; M3 bietet dazu eine vollständige Hilfe.</p>\n<div class=\"table-scroll wide-data-table\" tabindex=\"0\" aria-label=\"Breite Tabelle – horizontal verschiebbar\"><table>\n<thead>\n<tr class=\"header\">\n<th>Phase</th>\n<th style=\"text-align: right;\">Informieren / Analysieren</th>\n<th style=\"text-align: right;\">Planen</th>\n<th style=\"text-align: right;\">Entscheiden</th>\n<th style=\"text-align: right;\">Durchführen</th>\n<th style=\"text-align: right;\">Kontrollieren / Überprüfen</th>\n<th style=\"text-align: right;\">Reflektieren</th>\n<th style=\"text-align: right;\">Gesamt</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Orientierungszeit</td>\n<td style=\"text-align: right;\">25 Min.</td>\n<td style=\"text-align: right;\">20 Min.</td>\n<td style=\"text-align: right;\">20 Min.</td>\n<td style=\"text-align: right;\">70 Min.</td>\n<td style=\"text-align: right;\">30 Min.</td>\n<td style=\"text-align: right;\">15 Min.</td>\n<td style=\"text-align: right;\">180 Min.</td>\n</tr>\n</tbody>\n</table>\n</div><p><strong>Handlungsergebnis:</strong> Beschlussvorlage mit Zielsystem, Zielgruppenentscheidung und zusammenpassendem Strategiebündel. Diese Vorlage legt die Richtung fest; Rezeptur, Verpackung, Preise und konkrete Werbemittel werden erst anschließend ausgearbeitet.</p>\n<p><strong>Identischer Pflichtkern A–E:</strong> (1) Zielsegment anhand mindestens dreier Merkmale beschreiben und eine alternative Zielgruppe abwägen; (2) vier SMART formulierte Ziele mit Messverfahren, Verantwortung und mindestens zwei erläuterten Zielbeziehungen; die drei Rahmenziele aus M1 integrieren; (3) mindestens zwei vollständige Strategiebündel vergleichen, jeweils Wettbewerbsvorteil nach Porter, Marktbearbeitung und Produkt-Markt-Richtung; (4) ausgewählte Richtung mit zwei konkreten Handlungsfolgen und einer Abbruch-/Anpassungsregel begründen; (5) individuelle Erklärung der drei Strategieebenen ohne KI. Alle Wege arbeiten am gleichen fachlichen Anspruch.</p>\n</article></section></div></div>","m9.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M9 · Das nehmen Sie fachlich mit</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app onenote\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>OneNote</strong><span class=\"file\">Das nehmen Sie fachlich mit</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Start · Einfügen · Zeichnen · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><ul>\n<li>Ziele beschreiben Ergebnisse; Maßnahmen beschreiben Tätigkeiten auf dem Weg dorthin.</li>\n<li>Messbare Ziele benötigen Inhalt, Ausmaß, Zeit, Bezugsgröße und Zuständigkeit.</li>\n<li>Zielkonflikte werden durch Prioritäten und überprüfbare Ausgleichsmaßnahmen bearbeitet.</li>\n<li>Porter, Marktbearbeitung und Ansoff beantworten verschiedene strategische Fragen und werden kombiniert.</li>\n<li>Kostenführerschaft setzt einen Kostenvorteil voraus; ein niedriger Verkaufspreis allein genügt nicht.</li>\n<li>Strategie verlangt eine begründete Auswahl einschließlich bewusst zurückgestellter Möglichkeiten.</li>\n</ul>\n</article></section></div></div>","m10.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>M10 · Operatoren, Lernbegleitung und KI</h1></section><section class=\"card phase-materials material-access\" aria-label=\"Materialzugriff\"><h2>Materialzugriff</h2><nav class=\"material-grid\" aria-label=\"Materialien\"><a class=\"material-link\" href=\"m1.html\"><b>M1</b><span> · Strategischer Datenraum und Vorstandsauftrag</span></a><a class=\"material-link\" href=\"m2.html\"><b>M2</b><span> · Forschungs- und Marktbriefing für den isolierten Einstieg</span></a><a class=\"material-link\" href=\"m3.html\"><b>M3</b><span> · Ziele und Zielbeziehungen</span></a><a class=\"material-link\" href=\"m4.html\"><b>M4</b><span> · Drei Strategieebenen, die zusammenwirken</span></a><a class=\"material-link\" href=\"m5.html\"><b>M5</b><span> · Diskussionsangebote, keine fertigen Beschlüsse</span></a><a class=\"material-link\" href=\"m6.html\"><b>M6</b><span> · Beschlussvorlage und Entscheidungsmatrix</span></a><a class=\"material-link\" href=\"m7.html\"><b>M7</b><span> · Lehrbuch · Stichwörter und Seiten</span></a><a class=\"material-link\" href=\"m8.html\"><b>M8</b><span> · Ihr Auftrag im Überblick</span></a><a class=\"material-link\" href=\"m9.html\"><b>M9</b><span> · Das nehmen Sie fachlich mit</span></a><a class=\"material-link\" href=\"m10.html\"><b>M10</b><span> · Operatoren, Lernbegleitung und KI</span></a></nav></section><div class=\"source-document\"><div class=\"app onenote\"><div class=\"viewerbar\"><span class=\"dots\">•••</span><strong>OneNote</strong><span class=\"file\">Operatoren, Lernbegleitung und KI</span><span class=\"grow\"></span><span>— □ ×</span></div><div class=\"subbar\"><span>Start · Einfügen · Zeichnen · Ansicht</span><span class=\"zoom\">100 %</span></div><section class=\"canvas\"><article class=\"paper\"><p><strong>Entwickeln:</strong> Ziele und Strategiebündel aus den Falldaten erstellen. <strong>Vergleichen:</strong> Alternativen an denselben Kriterien prüfen. <strong>Begründen:</strong> Entscheidung mit Daten, Leitbild und Ressourcen verknüpfen. <strong>Beurteilen:</strong> Zielkonflikte und Risiken abwägen.</p>\n<p>KI kann optional eine kritische Vorstandsrolle simulieren oder unscharfe Zielformulierungen markieren; gleichwertig übernimmt dies ein Partner. M1/M2 bleiben die einzige Fallzahlenbasis. Fachliche Zuordnung, Beschluss und individueller Transfer werden von den Lernenden verantwortet. Mit wachsender Offenheit wechseln feste Zwischensicherungen zu selbst geplanten Kontrollen und bedarfsbezogenem Coaching.</p>\n</article></section></div></div>","erwartungshorizont.html":"<section class=\"card hero\"><div class=\"eyebrow\">BRC · LG03 · LS05 · Marketingziele und -strategien entwickeln</div><h1>Erwartungshorizont und Lehrkräftehinweise</h1></section><section class=\"card\"><p><strong>Dieser Teil enthält Lösungen und gehört nicht in die Schülerfassung.</strong></p>\n<h2 id=\"gemeinsamer-bewertungs--und-feedbackrahmen\">Gemeinsamer Bewertungs- und Feedbackrahmen</h2>\n<p>Die fünf Lernwege einer LS werden anhand desselben fachlichen Pflichtkerns beurteilt. Der Umfang eingesetzter Strukturhilfen ist kein automatischer Punkteabzug. Fachliche Richtigkeit, begründete Entscheidung und individuelle Erklärung werden von der Qualität der Lernorganisation getrennt rückgemeldet.</p>\n<div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 33%\">\n<col style=\"width: 33%\">\n<col style=\"width: 33%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Kriterium</th>\n<th>Tragfähiger Nachweis</th>\n<th>Nächster Schritt bei einer Lücke</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Fachliche Analyse und Rechnung</td>\n<td>Begriffe, Einheiten, Bezugsgrößen und Rechenwege stimmen; relevante Daten sind vollständig genutzt</td>\n<td>Eine fehlerhafte Zuordnung oder Rechnung mit Gegenbeispiel klären und neu anwenden</td>\n</tr>\n<tr class=\"even\">\n<td>Begründete betriebliche Entscheidung</td>\n<td>Kriterien, Alternativen, Zielkonflikte und Grenzen sind auf den konkreten Fall bezogen</td>\n<td>Eine bisher übergangene Alternative oder Annahme prüfen und Konsequenz benennen</td>\n</tr>\n<tr class=\"odd\">\n<td>Qualität des Handlungsergebnisses</td>\n<td>Adressat kann mit dem Produkt entscheiden oder handeln; Belege sind nachvollziehbar</td>\n<td>Fehlenden Entscheidungspunkt, Verantwortlichkeit oder Prüfindikator ergänzen</td>\n</tr>\n<tr class=\"even\">\n<td>Kontrolle und Überarbeitung</td>\n<td>Mindestens eine fachliche Gegenprüfung ist dokumentiert; Fehler werden berichtigt</td>\n<td>Eine unabhängige Rechnung, Datenkontrolle oder Gegenposition einholen</td>\n</tr>\n<tr class=\"odd\">\n<td>Individuelle Kompetenz</td>\n<td>Die Person erklärt wesentliche Zusammenhänge und löst den lokalen Kurztransfer ohne KI</td>\n<td>Gezielt nachlernen und denselben fachlichen Kern mit veränderten Daten erneut nachweisen</td>\n</tr>\n</tbody>\n</table>\n</div><p>Beobachtungen zur Kooperation, Selbstorganisation und Mediennutzung gehören in die Lernrückmeldung. Die konkrete Leistungsbewertung erfolgt nach den in der Fachgruppe vereinbarten Kriterien. Eine formal ansprechende Gruppenpräsentation kann einen nicht verstandenen Rechenweg nicht ausgleichen. Umgekehrt ist eine schlicht gestaltete, fachlich überzeugende Unterlage ein tragfähiges Handlungsergebnis.</p>\n<h2 id=\"zeiteinsatz-und-materialmenge\">Zeiteinsatz und Materialmenge</h2>\n<p>Die 80 UE umfassen je LS <strong>einen gewählten Lernweg</strong> einschließlich Diagnose, Bearbeitung, Kontrolle und Reflexion. Buchzugriff ist eine gezielte Hilfe innerhalb dieses Budgets. Optionale Begriffsspiele und Vertiefungen ersetzen bei Bedarf Wiederholungszeiten; sie werden nicht zusätzlich als Pflichtumfang aufgeschlagen. Für die Umsetzung kann die Lehrkraft aus dem vollständigen Material jeweils gezielt die benötigte Hilfe freigeben. In D/E entscheiden die Lernenden anhand ihres diagnostizierten Bedarfs selbst.</p>\n<h2 id=\"fachliche-kontrollpunkte-über-die-reihe\">Fachliche Kontrollpunkte über die Reihe</h2>\n<ul>\n<li><strong>LS01–03:</strong> Unternehmensumsatz, Teilmarkt und Produktfamilie nicht verwechseln. SWOT ist kein Sammelbecken beliebiger Aussagen. Der Produktlebenszyklus liefert eine begründete Deutung, keine gesicherte Prognose. Relativer Marktanteil verwendet den stärksten Wettbewerber als Bezugsgröße.</li>\n<li><strong>LS02:</strong> Die GmbH haftet bereits als Kapitalgesellschaft. Der Formwechsel selbst erzeugt keinen Mittelzufluss; eine spätere Aktienausgabe ist gesondert zu rechnen. AG bedeutet nicht automatisch Börsennotierung. Vorstand und Aufsichtsrat sind getrennte Organe.</li>\n<li><strong>LS04–06:</strong> Freiwillige Umfragen bleiben selektiv. Porter, Segmentierung und Ansoff beschreiben unterschiedliche, kombinierbare Strategieebenen. Neue Produktvariante, Produktvariation und Diversifikation sind nicht synonym. Nicht belegte Umwelt- oder Gesundheitsversprechen gehören nicht in das Produktkonzept.</li>\n<li><strong>LS07–09:</strong> FiBu und KLR überleiten; Monatsdaten nicht mit Jahreszielen vermischen. Mengen, Bestände und Normal-/Istwerte eindeutig halten. Gewinnzuschlag und Umsatzmarge unterscheiden. Bei Zusatzaufträgen zusätzliche Kosten und mögliche Verdrängung berücksichtigen, bei Engpässen nach dem relevanten knappen Faktor entscheiden.</li>\n<li><strong>LS10–12:</strong> Umsatz ist kein Gewinn, Reichweite keine Kaufzahl und ein Vorher-Nachher-Unterschied noch kein Kausalnachweis. Direkter Absatz kann durch einen Handelsvertreter unterstützt werden. Digitale Vertriebskanäle sind nicht automatisch umweltfreundlicher. Für einen Vergleich braucht es gleiche Leistungsumfänge und benannte Systemgrenzen.</li>\n</ul>\n</section><section class=\"card\"><p>Die folgenden Lösungen gehören nicht in die Arbeitsmaterialien während der Erarbeitung. Sie erläutern einen fachlich tragfähigen Referenzweg; alternative Entscheidungen erhalten bei gleicher Qualität der Begründung die gleiche Anerkennung. Der gewählte Lernweg A–E verändert weder die fachlichen Anforderungen noch die Bewertungskriterien. Selbstständigkeit und in Anspruch genommene Unterstützung können für Lernberatung dokumentiert werden, ohne die gleiche fachliche Leistung wegen der Lernwegwahl abzuwerten.</p>\n</section><section class=\"card\"><h3 id=\"rechenbasis-und-plausible-zielmatrix\">Rechenbasis und plausible Zielmatrix</h3>\n<p>Umsatzsteigerung: 2.640.000 − 2.400.000 = 240.000 Euro; 240.000 / 2.400.000 = 10 %. Verderb von 3,5 % auf 2,0 %: −1,5 Prozentpunkte, relativ −42,86 %. Die betriebliche Steuerung soll primär mit der eindeutig definierten Quote und derselben Mengenbasis arbeiten. Lokale gestützte Bekanntheit: 36/200 = 18 %; ein begründetes Ziel von 50/200 entspricht 25 % beziehungsweise +7 Prozentpunkten. Das Erreichen dieses Ziels ist ein Vorschlag, keine Prognose.</p>\n<div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 33%\">\n<col style=\"width: 33%\">\n<col style=\"width: 33%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Ziel</th>\n<th>Beispiel einer vollständigen Formulierung</th>\n<th>Messung / Verantwortung</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Umsatz</td>\n<td>Bis Ende GJ06 erzielt BioCasa im gesamten Unternehmen 2.640.000 Euro Nettoumsatz; gegenüber GJ05 sind dies +10 %.</td>\n<td>Monatsauswertung der Erlöse, quartalsweise Planvergleich; Christian/Vertrieb.</td>\n</tr>\n<tr class=\"even\">\n<td>Deckungsbeitrag</td>\n<td>Für GJ06 erreicht der absolute Jahres-Deckungsbeitrag mindestens 900.000 Euro; vor Freigabe größerer Absatzmaßnahmen werden die geplanten variablen Kosten geprüft.</td>\n<td>Einheitlich abgegrenzte Erlöse minus variable Kosten, monatliche Hochrechnung; Controlling. GJ05-Wert nicht angegeben und nicht zu erfinden.</td>\n</tr>\n<tr class=\"odd\">\n<td>Verderb</td>\n<td>Bis Ende GJ06 sinkt die Jahresquote verdorbener Mengen auf höchstens 2,0 % der produzierten Menge; monatliche Bestandsprüfung dient als Frühindikator.</td>\n<td>Gleiche Mengenerfassung wie beim GJ05-Wert 3,5 %; Aluna/Qualität.</td>\n</tr>\n<tr class=\"even\">\n<td>Psychologisches Ziel</td>\n<td>Bis Ende GJ06 erkennen mindestens 50 von 200 Befragten in der gleichartig wiederholten lokalen Erhebung die Marke nach Namensvorlage; Zwischenmessung nach dem ersten Piloten.</td>\n<td>Standort, Zeitfenster und Frageform konstant halten; Julia. Kein repräsentativer Wert für ganz Norddeutschland.</td>\n</tr>\n</tbody>\n</table>\n</div><p>Akzeptanz und Realistik werden nicht allein durch die Formulierung erfüllt. Die Vorlage muss eine Abstimmung der Rollen sowie die Annahme einer begrenzten, lernfähigen Umsetzung erkennen lassen. Ein anderes messbares viertes Marketingziel ist gleichwertig, sofern Datenbasis, Termin und Messung vorliegen; wenn ein Ausgangswert fehlt, muss zunächst eine Basismessung geplant werden.</p>\n<h3 id=\"zielgruppe-bündelvergleich-und-referenzbeschluss\">Zielgruppe, Bündelvergleich und Referenzbeschluss</h3>\n<p>Plausible Priorität: berufstätige Käufer im bestehenden norddeutschen Markt mit Bedarf an einem unkomplizierten Pizza-Abendessen zu Hause; erreichbare Einkaufsmöglichkeiten und Zugang zu Tiefkühlaufbewahrung und einem geeigneten Backofen sind Voraussetzungen. Zielgruppe nicht pauschal mit Alter, Einkommen oder „gesundheitsbewusster Persönlichkeit“ anreichern, wenn diese Merkmale nicht belegt sind. Die Auswahl wird durch 75 % Präferenz für die 400-g-Pizza innerhalb des entsprechenden Befragungssegments gestützt, bleibt jedoch explorativ. Familien mit Wunsch nach kombinierbaren Portionen sind eine ernsthafte Alternative.</p>\n<p>Eine konsistente Referenzkombination ist fokussierte Differenzierung über alltagstaugliche Qualität und nachvollziehbare Information, konzentrierte Marktbearbeitung berufstätiger Nutzer sowie Produktentwicklung im bestehenden norddeutschen Kundenmarkt. Der Niederlande-Pilot kann getrennt und begrenzt mit vorhandenen Produkten stattfinden und wäre dann Marktentwicklung. Neue Pizza ausschließlich im neuen niederländischen Markt wäre nach der festgelegten Marktgrenze Diversifikation; sie kombiniert zwei Unsicherheiten. Die drei Strategieebenen sind weder drei konkurrierende „Gewinner“ einer Matrix noch bloße Synonyme.</p>\n<p>Ein zweites vertretbares Bündel ist selektiv differenzierte Marktbearbeitung mit je einer Variante für Berufstätige und Familien. Dann müssen Komplexität, Zwei-Varianten-Grenze und Verderbziel ernsthaft abgewogen werden. Export-zuerst mit bestehenden Produkten ist ebenfalls begründbar, sofern ein begrenzter Pilot die Ressourcen nicht überfordert. Der Referenzanschluss der Reihe darf andere fachlich vertretbare Schülerentscheidungen nicht rückwirkend entwerten.</p>\n<p><strong>Zielbeziehungen:</strong> Bessere Absatzplanung kann Umsatz und Verderbquote gleichzeitig günstig beeinflussen. Mehr Varianten können zusätzliche Nachfrage erschließen, aber kleinere Lose und höhere Restbestände auslösen. Preisnachlässe können Umsatzmengen erhöhen und zugleich den Deckungsbeitrag je Einheit verringern; ohne Kosten- und Mengenprüfung ist die Wirkung auf den absoluten Jahres-DB offen. Transparente Nutzungshinweise können Kundenvertrauen stärken und Fehlanwendungen reduzieren.</p>\n<p><strong>Konkrete Folgen:</strong> Produktentwicklung erstellt ein Lastenheft für eine 400-g-Pizza und klar abgegrenzte Back-/Vorheizzeit; Logistik plant kleine, kontrollierbare Lose und erfasst Restbestände; Marketing erprobt nachvollziehbare Nutzenaussagen. Eine mögliche Anpassungsregel: „Wenn die monatliche Verderbquote im Pilot in zwei aufeinanderfolgenden Monaten über 2,5 % liegt, erfolgt vor der nächsten Ausweitung eine gemeinsame Überprüfung von Losgröße, Bestellrhythmus und Sortiment.“ Dieser Frühwarnwert ist eine vorgeschlagene Steuerungsregel, nicht eine zusätzlich behauptete Unternehmensvorgabe. Auch andere geeignete, messbare Regeln sind möglich.</p>\n<h3 id=\"bewertung-und-typische-fehler\">Bewertung und typische Fehler</h3>\n<div class=\"table-scroll\"><table>\n<colgroup>\n<col style=\"width: 42%\">\n<col style=\"width: 57%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Kriterium</th>\n<th style=\"text-align: right;\">Gewicht</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Zielgruppenwahl einschließlich Alternative und Datenbegrenzung</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">20 %</td>\n</tr>\n<tr class=\"even\">\n<td>Vier Ziele, Messverfahren, Verantwortung und Zielbeziehungen</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">30 %</td>\n</tr>\n<tr class=\"odd\">\n<td>Fachlich richtiger Vergleich zweier Strategiebündel</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">30 %</td>\n</tr>\n<tr class=\"even\">\n<td>Umsetzungsfolgen und konkrete Anpassungsregel</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">10 %</td>\n</tr>\n<tr class=\"odd\">\n<td>Individueller Transfer</td>\n<td style=\"text-align: right;\" class=\"numeric-cell\">10 %</td>\n</tr>\n</tbody>\n</table>\n</div><p>Typische Fehler: Maßnahme als Wirkungsziel; aus SMART automatisch Realistik folgern; Deckungsbeitrag gleich Gewinn; Kostenführerschaft gleich billiger Verkauf; kleiner Marktanteil gleich bewusste Nischenstrategie; Produktentwicklung, Porter und Segmentierung gegeneinander „abwählen“; Marktdefinition bei Ansoff wechseln. Eine Punkte-Matrix mit attraktiven Summen kompensiert keine Verletzung der Positionierungs- oder Ressourcenbedingungen.</p>\n<p><strong>Qualitätscheck:</strong> Die 180 Minuten dienen einer kurzen, entscheidungsfähigen Vorlage. Die Lehrkraft sollte keine zusätzliche umfangreiche Präsentation verlangen. Das Gruppenpuzzle in C wird auf die tatsächlich benötigten Entscheidungsperspektiven begrenzt.</p>\n</section>"},"pageTitles":{"index.html":"Orientierung","handlungssituation.html":"Handlungssituation","informieren.html":"Informieren","planen.html":"Planen","entscheiden.html":"Entscheiden","durchfuehren.html":"Durchführen","bewerten.html":"Überprüfen","reflektieren.html":"Reflektieren","m1.html":"M1 · Strategischer Datenraum und Vorstandsauftrag","m2.html":"M2 · Forschungs- und Marktbriefing für den isolierten Einstieg","m3.html":"M3 · Ziele und Zielbeziehungen","m4.html":"M4 · Drei Strategieebenen, die zusammenwirken","m5.html":"M5 · Diskussionsangebote, keine fertigen Beschlüsse","m6.html":"M6 · Beschlussvorlage und Entscheidungsmatrix","m7.html":"M7 · Lehrbuch · Stichwörter und Seiten","m8.html":"M8 · Ihr Auftrag im Überblick","m9.html":"M9 · Das nehmen Sie fachlich mit","m10.html":"M10 · Operatoren, Lernbegleitung und KI","erwartungshorizont.html":"Erwartungshorizont und Lehrkräftehinweise"},"printOrder":["index.html","handlungssituation.html","informieren.html","planen.html","entscheiden.html","durchfuehren.html","bewerten.html","reflektieren.html","m1.html","m2.html","m3.html","m4.html","m5.html","m6.html","m7.html","m8.html","m9.html","m10.html"],"workbook":"pdf/GoodNotes_LG03_LS05_W1.pdf","workbooks":{"1":"pdf/GoodNotes_LG03_LS05_W1.pdf","2":"pdf/GoodNotes_LG03_LS05_W2.pdf","3":"pdf/GoodNotes_LG03_LS05_W3.pdf","4":"pdf/GoodNotes_LG03_LS05_W4.pdf","5":"pdf/GoodNotes_LG03_LS05_W5.pdf"},"phaseBudgets":{"informieren":25,"planen":20,"entscheiden":20,"durchfuehren":70,"bewerten":30,"reflektieren":15},"sourceTaskCounts":{"informieren":{"1":1,"2":1,"3":1,"4":1,"5":1},"planen":{"1":1,"2":1,"3":1,"4":1,"5":1},"entscheiden":{"1":1,"2":1,"3":1,"4":1,"5":1},"durchfuehren":{"1":1,"2":1,"3":1,"4":1,"5":1},"bewerten":{"1":1,"2":1,"3":1,"4":1,"5":1},"reflektieren":{"1":1,"2":1,"3":1,"4":1,"5":1}},"materialSources":{"m1.html":{"title":"Strategischer Datenraum und Vorstandsauftrag","kind":"acrobat","sourceKey":"M1"},"m2.html":{"title":"Forschungs- und Marktbriefing für den isolierten Einstieg","kind":"acrobat","sourceKey":"M2"},"m3.html":{"title":"Ziele und Zielbeziehungen","kind":"onenote","sourceKey":"M3"},"m4.html":{"title":"Drei Strategieebenen, die zusammenwirken","kind":"onenote","sourceKey":"M4"},"m5.html":{"title":"Diskussionsangebote, keine fertigen Beschlüsse","kind":"teams","sourceKey":"M5"},"m6.html":{"title":"Beschlussvorlage und Entscheidungsmatrix","kind":"onenote","sourceKey":"M6"},"m7.html":{"title":"Lehrbuch · Stichwörter und Seiten","kind":"acrobat","sourceKey":"book_access"},"m8.html":{"title":"Ihr Auftrag im Überblick","kind":"onenote","sourceKey":"assignment_overview"},"m9.html":{"title":"Das nehmen Sie fachlich mit","kind":"onenote","sourceKey":"section7"},"m10.html":{"title":"Operatoren, Lernbegleitung und KI","kind":"onenote","sourceKey":"section8"}}};
